values (site, , , $site_en0${"nav":{"logo_text":"Greddys Martinez","links":[{"label":"Projects","href":"/projects"},{"label":"Resume","href":"/resume"},{"label":"Contact","href":"/contact"}],"cta_label":"Get in touch","cta_href":"/contact"},"home":{"hero":{"greeting":"I am Greddys Martinez","tagline":"a designer in AI Research & UX / UI","photo":"/images/projects/benefits-enrollment/hero/benefits-hero.png","methodology_chips":["Classic","Agile based","Product Prototype","Digital Prototype","Expert Reviews"]},"trusted_by":{"label":"Collaborated with","clients":[{"name":"IBX","logo":"/images/SNUZw.png"},{"name":"Skill","logo":"/images/IbuV3.png"},{"name":"Hakuna","logo":"/images/hakuna.avif"},{"name":"Nayya","logo":"/images/bBw3A.png"},{"name":"Paychex","logo":"/images/c54fy.png"},{"name":"Paramount+","logo":"/images/paramount-plus.svg"},{"name":"Zapiano","logo":"/images/zapiano-logo.svg"},{"name":"Habitat for Humanity","logo":"/images/habitat-for-humanity.svg"},{"name":"Elevation","logo":"/images/elevation-mark.png"}]},"certifications":[{"name":"Upwork Certification","logo":"/images/iNSrn.png"},{"name":"NN/g UX Certification","logo":"/images/OiSjn.png"}],"stat_banner":{"text":"Last quarter, my clients saw a","value":"47%","value_label":"average increase in conversions.","cta_headline":"Your product deserves that too.","cta_label":"Let's work together →","cta_href":"#contact"},"tools_section":{"headline":"Tools I Love & Work With","description":"I integrate seamlessly with the tools your team already uses, creating workflows that feel natural and efficient.","cta_label":"View My Resume →","cta_href":"/resume","row_1":["Figma","Framer","Miro","React","Node","Python","Swift","TS","Vue","Go","SQL"],"row_2":["GitHub","Slack","AWS","Vercel","Docker","Tailwind","Next.js","Rust","Redis","GPT","GCP"]}},"footer":{"tagline":"Senior Product Designer crafting thoughtful digital experiences that make a difference.","cta_headline":"Let's Work Together","cta_body":"I'm always open t