insert into public.case_study_locales (case_study_id, locale, payload)
select id, , $case_en0${"slug":"benefits-enrollment","status":"published","featured":true,"order":4,"title":"Self-Service Access and Role Management","company":"Paychex & Flock","client_context":"Paychex & Flock","role":"Senior Product Designer (Growth & Monetization)","year":2025,"duration":"3 months","industry":"BENEFITS / ENSURANCE SAAS","tagline":"Replaced a manual workflow with a centralized, self-managed platform; cutting processing time by 72%.","tags":["BENEFITS / ENSURANCE SAAS","UX Research","IA","Interaction Design","Design Systems"],"tools":["Jira","Miro","Webex","Outlook","Copilot","Hotjar"],"images":{"cover":"/images/projects/benefits-enrollment/thumbnails/thumbnail-benefits.png","hero":"/images/projects/benefits-enrollment/hero/benefits-hero.png","gallery":["/images/benefits/figma-logo.png","/images/benefits/jira-logo.png","/images/benefits/miro-logo.png"]},"client_logos":[{"name":"Paychex","logo":"/images/c54fy.png"},{"name":"Flock","logo":"/images/flock-logo.png"},{"name":"IBX","logo":"/images/SNUZw.png"}],"metrics":[{"value":"72%","label":"Reduction in processing time","context":"benefits processing"},{"value":"500+","label":"Employees self-managed","context":"without IT tickets"},{"value":"3 mo","label":"End-to-end design & delivery","context":"timeline"}],"team":["Product Owner","Program manager","Business analyst","Researcher","Dev team (12)","UX manager","UX Lead","UX/UI designer","Service architect","Scrum master"],"my_role":["User Research","UX/UI Design","Product Thinking","Narrative"],"problem":{"admin_pain_points":["Benefits changes required running multiple payroll cycles and manual reconciliation.","Admins had no easy way to aggregate employee data across departments in one place.","When enrollment spikes occurred, there was no clear escalation or alert workflow."],"user_pain_points":["Adding new employees required support tickets and manual development effort.","Data needed to be collected, validated and sent across teams. Changes were tracked through emails.","No centralized governance or clear permission structure."]},"constraints":["An aggressive timeline.","Balancing the product's existing patterns with user needs without disrupting the experience."],"methodology":{"name":"Design Thinking","steps":[{"step":1,"label":"Empathize","description":"User interviews & stakeholder sessions"},{"step":2,"label":"Define","description":"Problem framing & pain point mapping"},{"step":3,"label":"Ideate","description":"Flows, architecture & wireframing"},{"step":4,"label":"Prototype","description":"Hi-fi screens & interactive prototypes"},{"step":5,"label":"Test","description":"Post-launch Hotjar analysis"}]},"design_strategy":["Define the underlying architecture and logic before changing the UI.","Find what parts of the system work well and build around those.","With no design system, collaboration with the development team ensured the forward-facing UI remained cohesive throughout."],"reflections":[{"title":"Architecture before UI.","body":"Investing time in mapping the permission model before designing screens prevented costly rework. The logic had to be airtight before any pixel moved."},{"title":"Trust through constraints.","body":"Working without a design system forced tight collaboration with engineers. Constant syncs kept the UI cohesive and the handoff smooth even under timeline pressure."}],"nda_notice":"Parts of this presentation,including some screens and project details,have been redacted or blurred due to a confidentiality agreement signed with the client. The work shown is real; full details are withheld to protect client privacy.","password":null,"external_link":null}$case_en0$::jsonb
from public.case_studies
where slug = 
on conflict (case_study_id, locale) do update
set payload = excluded.payload;

insert into public.case_study_locales (case_study_id, locale, payload)
select id, , $case_en0${"slug":"nayya-ai-benefits","status":"published","featured":true,"order":1,"title":"Nayya Integration","company":"Nayya","client_context":"Paychex via ITX Corp","role":"Sr. Product Designer","year":2025,"duration":"6 months","industry":"AI Benefits / HR SaaS","tagline":"Designed the integration of Nayya as an AI-powered benefits tool, guiding employees to choose coverage that matched their needs.","tags":["BENEFITS / ENSURANCE SAAS","UX Research","IA","Interaction Design","Design Systems"],"tools":["Figma","Jira","Miro","Webex","Outlook","Copilot","Hotjar"],"filters":["UX Research","Product Design","AI Product"],"images":{"cover":"/images/projects/nayya-ai-benefits/thumbnails/thumbnail-nayya-cover.png","hero":"/images/projects/nayya-ai-benefits/hero/nayya-hero.png","gallery":[]},"client_logos":[{"name":"Nayya","logo":"/images/bBw3A.png"},{"name":"Paychex","logo":"/images/c54fy.png"}],"metrics":[{"value":"307%","label":"IRR","context":"Projected ROI,estimated return from increased plan uptake (NPV $11.4M)."},{"value":"~115,500","label":"Annual Benefits","context":"Enrollments completed 5% above the 100K goal."},{"value":"67%","label":"Conversion Rate","context":"Users who received Nayya recommendations that fit their needs and enrolled in a plan."}],"team":["UX Lead","Content Designer","Product Owner","Business Analyst","Solution Leads"],"my_role":["UX Strategy","Integration UX","User Research","Product Thinking"],"problem":{"admin_pain_points":["A seamless embedded integration between Flex and Nayya Choose was not feasible under the technical constraints.","The team needed to balance business value, technical limitations, and user confidence during a sensitive decision-making process."],"user_pain_points":["Employees needed more support when selecting benefits and choosing coverage that matched their needs.","Users would need to leave Flex and access Nayya Choose in a separate experience.","The transition needed clearer communication, stronger context, and visual cues that made the handoff feel intentional and trustworthy."]},"constraints":["A seamless embedded integration between Flex and Nayya Choose was not technically feasible.","The project moved on an aggressive timeline with significant technical limitations.","The experience had to protect user confidence during benefits decision-making."],"methodology":{"name":"Research & Discovery","steps":[{"step":1,"label":"Understand","description":"Clarified the benefits selection journey and Nayya Choose's role in decision support."},{"step":2,"label":"Define","description":"Identified the feasible integration path between Flex and the external Nayya experience."},{"step":3,"label":"Align","description":"Collaborated with the Solution Leads, Product Onwer, Business Analyst and Devs."},{"step":4,"label":"Validate","description":"Recommended user testing to understand concerns before finalizing the handoff."},{"step":5,"label":"Measure","description":"Used enrollment behavior and revenue projections to evaluate impact."}]},"design_strategy":["Define a realistic integration path instead of forcing an embedded experience that the platform could not support.","Use communication and visual cues to explain where users were going, why the transition mattered, and how Nayya Choose supported their benefits decisions.","Protect continuity between Flex and Nayya Choose by making the handoff feel intentional, trustworthy, and aligned with the broader enrollment journey."],"reflections":[{"title":"Designing under constraints.","body":"Designing under technical constraints does not mean compromising the experience. It means finding the most effective path within the boundaries you are given."},{"title":"Test early, fix early.","body":"User testing, even at a small scale, surfaces the decisions that matter most before they become expensive to fix."},{"title":"Trust is a design problem.","body":"When users cross platform boundaries, clarity and context are what keep them moving forward."},{"title":"Constraints force focus.","body":"The inability to embed Nayya natively pushed the team to invest in transition design, an area that is often overlooked when seamless integration feels like the obvious solution."}],"nda_notice":null,"password":null,"external_link":null,"content_blocks":[{"id":"overview","type":"overview","title":"Project Overview","body":""},{"id":"team-context","type":"custom","title":"Team","body":"I worked closely with the UX Lead and Content Designer to ensure consistency in both experience and messaging under a tight timeline. I also collaborated with the Product Owner, Business Analyst, and Solution Leads to align the proposed experience with business goals and technical realities."},{"id":"situation","type":"custom","title":"Situation","body":"Employees needed more support when selecting benefits, and Nayya Choose offered a strong recommendation engine to guide them toward more relevant coverage.\n\nThe project moved on an aggressive timeline and came with significant technical limitations. A seamless embedded integration between Flex and Nayya Choose was not feasible."},{"id":"task","type":"custom","title":"Task","body":"I was responsible for helping define the best integration path between the two platforms while protecting the user experience as much as possible.\n\nThis meant balancing business value, technical constraints, and user confidence during a sensitive decision-making process."},{"id":"actions","type":"custom","title":"Actions","body":"Because a seamless integration was not possible, we identified that users would need to leave Flex and access Nayya Choose in a separate experience.\n\nTo reduce friction, I helped recommend user testing to better understand concerns before finalizing the experience.\n\nThe research showed users needed clearer communication about where they were going, why the transition mattered, and visual cues that made the handoff feel intentional and trustworthy."},{"id":"impact","type":"results","title":"Impact","body":"The integration showed clear value for users who engaged with Nayya Choose. Participants who completed the survey enrolled in twice as many benefits as those who skipped it, and the work contributed to measurable growth across medical, ancillary, and PEO revenue.","payload":{"rows":[{"metric":"Annual growth target - Medical","value":"2%"},{"metric":"Annual growth target - Ancillary","value":"8%"},{"metric":"FY26 medical growth","value":"$1M"},{"metric":"FY26 ancillary growth","value":"$2M"},{"metric":"Full-year impact - Flex","value":"$6M"},{"metric":"Full-year impact - All PEO","value":"$10M"}],"insights":["Baseline average plans per participant (2023-2025): 4.46","2026","• Participants who \"skipped\" Nayya: 2.57","• Participants who only \"started\" Nayya: 4.43","• Participants who got recommendations from Nayya: 5.44"],"opportunities":["Less than 7% of eligible employees completed a Nayya survey, leaving strong room for growth.","Increasing completion to 10% could add 10,000+ plans and generate $2M-$7M in incremental PEO benefits revenue.","Further research opportunities include deeper analysis of Nayya survey behavior and year-over-year enrollment changes.","Potential product expansion areas include 401(k), FinFit, and PayActiv recommendations."]}}]}$case_en0$::jsonb
from public.case_studies
where slug = 
on conflict (case_study_id, locale) do update
set payload = excluded.payload;

insert into public.case_study_locales (case_study_id, locale, payload)
select id, , $case_en0${"slug":"flock-accessibility-system","status":"published","featured":false,"order":2,"title":"Flock Accessibility Audit & Design System Unification","company":"Flock","client_context":"Paychex via ITX Corp","role":"Product Designer","year":2025,"duration":"6 months audit + 1 year build","industry":"Accessibility / Design Systems","tagline":"Led an accessibility audit and helped unify the design system. This reduced pattern debt, made the product more consistent, and improved collaboration between design and development teams.","tags":["Accessibility","Design Systems","UX Research","Product Design","Axe","Design system","Voice Over"],"filters":["Accessibility","Design Systems","Product Design"],"tools":["Figma","Jira","Miro"],"images":{"cover":"/images/projects/flock-accessibility-system/thumbnails/flock.png","hero":"/images/projects/flock-accessibility-system/hero/flock-hero.png","gallery":[]},"client_logos":[],"metrics":[{"value":"6 months","label":"Audit and prioritization","context":"initial accessibility and system review"},{"value":"1 system","label":"Shared foundation","context":"aligned patterns, typography, icons, and dialogs"}],"team":["1 designer","UX Lead","UX Manager","Product Owner","Business Analyst","3 developers","Dev Lead"],"my_role":["Accessibility Audit Lead","Component Strategy","Design Systems","Engineering Partnership"],"problem":{"admin_pain_points":["The product had accessibility risk across core flows and no mature shared library to address issues systematically.","Teams were working with duplicated patterns, inconsistent naming, and fragmented component behavior across pages.","Weak documentation and handoff ambiguity created implementation friction and made system decisions harder to scale."],"user_pain_points":["Inconsistent components made the experience less predictable from page to page.","Accessibility gaps reduced clarity and usability for people relying on stronger hierarchy, focus treatment, and consistent interaction states.","Dialogs, icons, typography, and responsive behavior lacked enough shared rules to feel cohesive across the product."]},"constraints":["Accessibility improvements had to happen while the product was live and already fragmented across multiple pages and patterns.","There was no fully mature design system in place, so audit work and system definition had to progress together.","The system needed to support real engineering constraints, QA, and implementation readiness rather than remain a Figma-only cleanup effort."],"methodology":{"name":"Audit to Systemization","steps":[{"step":1,"label":"Audit","description":"Checked for accessibility issues and components that didn't match the system."},{"step":2,"label":"Structure","description":"Grouped problems by importance to see what to fix first."},{"step":3,"label":"Systemize","description":"Created clear patterns, states, and rules for how components should work."},{"step":4,"label":"Align","description":"Worked with developers to make sure designs could be built correctly in React."},{"step":5,"label":"Validate","description":"Reviewed designs and builds, using feedback to improve consistency."}]},"design_strategy":["Clarify foundations, components, patterns, and modules so teams know when to use each pattern and how it should behave.","Separated accessibility fixes from design-system decisions by documenting patterns, variants, states, and usage rules.","Worked closely with developers to adapt component decisions to implementation realities, QA needs, and handoff clarity.","Used design review, accessibility checks, and implementation feedback to strengthen adoption and consistency."],"reflections":[{"title":"Usability is about revealing what matters.","body":"Usability isn't about removing; it's about revealing what matters. This project proves that accessibility, performance, and UX all strengthen each other when treated as one discipline."}],"nda_notice":null,"password":null,"external_link":null,"content_blocks":[{"id":"overview","type":"overview","title":"Overview","body":""},{"id":"team-context","type":"custom","title":"Team","body":"I led the audit framing, defined which patterns needed consolidation, and partnered with engineering on how components should behave in build. I worked alongside another designer, in collaboration with a UX Lead, UX Manager, Product Owner, Business Analyst, three developers, and a Dev Lead."},{"id":"situation","type":"custom","title":"Situation","body":"The lack of a design system meant icons, typography, dialogs, repeated interface patterns, inconsistent component behavior, and reusable UI patterns had drifted over time.\n\nThat created friction for implementation, affected accessibility readiness, made handoffs less reliable, and increased the cost of maintaining consistency in the experience."},{"id":"task","type":"custom","title":"Task","body":"My role was to turn accessibility findings and UI inconsistencies into a clear system direction to define reusable patterns that design and engineering could adopt.\n\nThe product had been recently acquired, so the goal was to keep its visual identity while improving consistency and usability through a more scalable, React-based system.\n\nSuccess meant reducing duplicated patterns, improving the product, clarifying handoff expectations, and creating stronger accessibility guidance for future work."},{"id":"actions","type":"custom","title":"Actions","payload":{"items":["I built an audit framework that grouped issues by severity, system impact, and implementation complexity, while separating accessibility findings, system inconsistencies, and engineering constraints for clearer decision-making.","I reviewed foundations and shared patterns across icons, typography, dialogs, and components to identify where states, variants, naming, and responsive behavior needed to be standardized. From that, I defined reusable patterns and clearer guidance in Figma to reduce ambiguity and improve handoff consistency.","I also partnered closely with developers during review and QA to adapt patterns to real technical constraints and confirm that the proposed system decisions worked in build."]}},{"id":"impact","type":"results","title":"Product/System Outcomes","body":"The project created a clearer system foundation for accessibility, component reuse, and implementation consistency. Because confirmed business metrics were not preserved, the outcomes are framed through product, system, and delivery signals.","payload":{"rows":[{"metric":"Accessibility risk","value":"Lowered"},{"metric":"Pattern debt","value":"Reduced"},{"metric":"Handoff clarity","value":"Stronger"}],"insights":["The audit made severity and prioritization visible, which helped the team address structural accessibility problems instead of isolated UI fixes.","Shared guidance for icons, typography, dialogs, and reusable patterns reduced inconsistency and gave the system a clearer source of truth.","Defining states, variants, and usage rules reduced ambiguity between design and engineering and improved the quality of implementation conversations."],"projected":["A clearer adoption path for reusable components, patterns, and modules.","More reliable handoff and QA because accessibility notes and usage guidance are documented.","Lower risk in future accessibility reviews by addressing issues systemically instead of page by page.","Pattern consistency helps users understand the interactions on the pages."],"successMetrics":["Reduction of duplicated or conflicting component patterns.","Improved components’ states, variants, and responsive behavior across reused modules.","Fewer implementation questions during handoff and QA.","Accessibility issues identified and resolved by severity before release."]}}]}$case_en0$::jsonb
from public.case_studies
where slug = 
on conflict (case_study_id, locale) do update
set payload = excluded.payload;

insert into public.case_study_locales (case_study_id, locale, payload)
select id, , $case_en0${"slug":"i9-everify-integration","status":"published","featured":false,"order":3,"title":"I-9 & E-Verify Integration","company":"Paychex Flex","client_context":"Paychex via ITX Corp","role":"Sr. Product Designer","year":2024,"duration":"Around 3 years","industry":"HR Compliance / Onboarding SaaS","tagline":"Redesigned the I-9 and E-Verify integration for Flex, increasing post-launch completion from 69% to 81% and reducing completion time by 26%.","tags":["UX Research","Product Design","Workflow Design","Compliance"],"filters":["UX Research","Product Design","Compliance"],"tools":["Figma","Jira","Miro","Webex","Outlook","Copilot"],"images":{"cover":"/images/projects/i9-everify-integration/thumbnails/i9-thumbnail.png","hero":"/images/projects/i9-everify-integration/hero/i9-banner.png","gallery":[]},"client_logos":[{"name":"Paychex","logo":"/images/c54fy.png"}],"metrics":[{"value":"76%","label":"of Flex clients lacked a compliant I-9 workflow"},{"value":"26","label":"Rounds of exploration & testing"},{"value":"2,548","label":"Survey responses post first release"}],"team":["Product Owner","Program Manager","Business Analyst","Researcher","Dev Team (12)","UX Manager","UX Lead","UX/UI Designer","Service Architect","Scrum Master"],"my_role":["User Research","UX/UI Design","Product Thinking","Narrative"],"problem":{"admin_pain_points":["Clients often relied on manual processes or custom off-platform solutions to manage I-9 and E-Verify requirements.","Admins needed clearer status tracking, document access, vendor handoff visibility, and transaction-based billing tied to onboarding.","The experience had to support multiple user roles, future scalability, and compliance-driven workflows."],"user_pain_points":["New hires needed to complete Section 1 of Form I-9 as part of onboarding without feeling disconnected from the Flex experience.","Users needed stronger cues before leaving Flex for the external HIREtech experience.","Employees and admins needed clearer ownership, progress states, completion feedback, and follow-up actions."]},"constraints":["The workflow depended on HIREtech, a third-party vendor experience outside Flex.","The design had to account for employee and admin journeys, compliance constraints, vendor redirects, billing requirements, and status tracking.","The product needed to scale for shared workers, same-FEIN clients, white-label support, and migration of existing I-9 documents."],"methodology":{"name":"Design Thinking","steps":[{"step":1,"label":"Research","description":"Conducted design explorations and testing across user journeys."},{"step":2,"label":"Map","description":"Mapped where the workflow should begin in Flex and where users would transition into HIREtech."},{"step":3,"label":"Align","description":"Aligned I-9 with familiar onboarding task patterns like W-4 and direct deposit."},{"step":4,"label":"Clarify","description":"Defined handoff moments, status visibility, task ownership, and completion feedback."},{"step":5,"label":"Scale","description":"Considered future needs including shared workers, same-FEIN clients, white-label support, and document migration."}]},"design_strategy":["Use clearer handoff messaging, progress states, and completion feedback to reduce confusion around the external HIREtech experience."],"reflections":[{"title":"What worked.","body":"Anchoring a compliance-heavy workflow to familiar onboarding patterns made I-9 feel native to the product rather than a bolted-on task. A single usability test with 7 users was enough to shift a product decision and protect a better experience,data beats opinion. Combining iterative testing with clear handoff strategy created a stronger foundation for both usability and business growth."},{"title":"What I’d do differently.","body":"Establish third-party alignment earlier,waiting on compliance validation from HIREtech created rework and slowed design iterations. Moving faster through compliance content decisions by setting clearer approval checkpoints upfront, rather than iterating in circles, would have saved time."},{"title":"What this unlocked.","body":"The project exposed a missing pattern in Flex for communicating third-party transitions to users. Solving it here created a reusable transparency pattern that addressed a systemic problem affecting multiple integrations across the platform."}],"nda_notice":null,"password":null,"external_link":null,"content_blocks":[{"id":"situation","type":"custom","title":"Situation","body":"Flex clients were completing I-9 and E-Verify requirements outside the platform, relying on manual coordination, off-platform tools, and admin follow-up to close compliance gaps.\n\nAround 76% of users were affected, creating inconsistent completion rates, higher error risk, and increased support burden across hiring workflows.\n\nWithout a native workflow, there was no reliable way to track status, confirm ownership, or ensure compliance was completed on time."},{"id":"task","type":"custom","title":"Task","body":"","payload":{"items":["Owned the end-to-end UX process as sole designer, from research to final handoff.","Designed for both the employee journey (Section 1) and the admin journey (Section 2 and status tracking).","Integrated I-9 and E-Verify into Flex without fragmenting the existing onboarding experience.","Facilitated a working session with BAs, engineers, and product leads to surface open questions, integration constraints, and third-party gaps with HIREtech."]}},{"id":"alternatives","type":"custom","title":"Alternatives explored","body":"","payload":{"subtitle":"","items":[]}},{"id":"research","type":"custom","title":"The Solution","body":"","payload":{"items":[],"delivery_items":["Delivered detailed design specs for development including behaviors, content examples, component definitions, and edge case documentation.","Designed email communications to announce the new integration and follow up with users who did not complete the I-9 process.","Created handoff guidelines documenting how the Flex to HIREtech integration was communicated to users, covering redirect messaging, progress states, and completion feedback."]}},{"id":"actions","type":"custom","title":"Actions","body":"","payload":{"items":[]}},{"id":"impact","type":"results","title":"Result","body":"","payload":{"rows":[{"metric":"Task completion rate from employee","value":"12%"},{"metric":"Avg time on task","value":"−26%"},{"metric":"Redirect hesitation","value":"−13%"},{"metric":"Status interpretation errors","value":"−9%"},{"metric":"User confidence score","value":"0.8"}],"insights":["Task completion rate,69% (early concept) to 81% (refined concept).","Average time on task,4m 12s to 3m 06s.","Redirect hesitation reduced from 46% to 33%.","Status interpretation errors down from 31% to 22%.","User confidence score improved from 3.2/5 to 4.0/5.","Manual process dependency baseline established at 60–70%; target set at under 25% for post-launch tracking.","2,548 survey responses post first release confirmed the integrated direction was working."],"opportunities":["Employees leaving mid-flow had no way to save progress, creating drop-off risk and incomplete I-9 submissions.","Adding form save state could directly improve completion rates and reduce admin follow-up for unfinished cases.","Content misalignment between HIREtech and Flex was identified in testing; updated communication guidelines were delivered and awaiting HIREtech confirmation.","The transparency pattern developed for this integration opens the door to applying the same handoff strategy across other third-party workflows in Flex."]}}]}$case_en0$::jsonb
from public.case_studies
where slug = 
on conflict (case_study_id, locale) do update
set payload = excluded.payload;

insert into public.case_study_locales (case_study_id, locale, payload)
select id, , $case_en0${"slug":"protecta","status":"published","featured":false,"order":6,"title":"Brand, Website & Campaign Launch","company":"Protecta Advisory","client_context":"Protecta Advisory","role":"Design Engineer","year":2026,"duration":"72% faster website delivery","industry":"Insurance / Advisory","tagline":"Designed an insurance-awareness campaign and conversion path that turns social-media reach into direct WhatsApp inquiries and qualified consultation opportunities.","tags":["AI Product","Product Design","Brand Strategy","Content Design","Accessibility","Localization"],"filters":["AI Product","Product Design","Accessibility"],"tools":["NotebookLM","Claude","Figma AI","Codex","Claude Code","Storybook","Grammarly","Vercel"],"images":{"cover":"/images/projects/protecta/thumbnails/protectabanner.png","hero":"/images/projects/protecta/hero-banner.png","gallery":["/images/projects/protecta/screenshots/protecta-home-desktop.png","/images/projects/protecta/screenshots/protecta-home-mobile.png"]},"client_logos":[],"metrics":[{"value":"72%","label":"Faster website delivery","context":"AI-assisted workflow across brand, bilingual content, website design and build, QA, and launch."},{"value":"98%","label":"New-audience reach","context":"Views from non-followers in the first 28 days of the campaign."},{"value":"WCAG 2.1 AA","label":"Accessibility target","context":"Component-level accessibility checks were handled in Storybook during the build."}],"team":["Solo designer","Client advisors","Client founders for final approvals"],"my_role":["UX/UI Designer","Brand Strategist","Content Strategist & Writer","Product Owner","Developer","QA Engineer","Bilingual Localization Lead"],"problem":{"admin_pain_points":["Protecta had a clear service model and strong referral engine but no brand system, no live site, and no structured content to support growth.","The referral program, advisory model, and WhatsApp contact path all needed to be explained clearly in a way that felt trustworthy for families making sensitive insurance decisions."],"user_pain_points":["Prospects needed a warmer, more human alternative to the call-center experience they usually associate with insurance websites.","Spanish-speaking families needed content that felt native and culturally natural, not like a direct translation of an English-first site.","Visitors needed a clear understanding of the referral program and an easy path to contact the advisors without friction."]},"constraints":["A compressed timeline across strategy, brand, content, design, build, QA, and deployment.","No existing brand system, no prior website, and no ready-to-publish content.","No direct user research in the timeline; advisor interviews and client knowledge acted as proxy user signal."],"methodology":{"name":"AI-Augmented Delivery Workflow","steps":[{"step":1,"label":"Capture","description":"Ran a structured client call and questionnaire to capture audience needs, sales flow, objections, referral mechanics, and tone as the source of truth."},{"step":2,"label":"Research","description":"Used NotebookLM to synthesize industry patterns, competitive positioning, bilingual insurance norms, and structural opportunities quickly."},{"step":3,"label":"Brand","description":"Used Claude Design for the first visual draft, then selected and iterated the strongest directions based on research, structure, and design judgment."},{"step":4,"label":"Write","description":"Used Claude for first-pass copy drafts, then rewrote the messaging hierarchy and adapted the Spanish content natively."},{"step":5,"label":"Design","description":"Used Figma AI to turn the selected direction into a reusable component library, then iterated the homepage and internal pages with those components, variants, and bilingual states."},{"step":6,"label":"Build","description":"Used the Figma component library as the implementation reference. Generated scaffolding with Codex, finished implementation details with Claude Code, and hand-tuned the result into production-quality output."},{"step":7,"label":"Validate","description":"Kept the Figma library and coded components aligned, documented implementation states in Storybook, checked accessibility against WCAG 2.1 AA, and deployed the working product to Vercel for client review."}]},"design_strategy":["The project was structured around one core decision: use AI to compress research, copy scaffolding, and build acceleration, while reserving design judgment for brand tone, hierarchy, accessibility, and trust-building moments.","Because Protecta's differentiator is human-led, year-round advisory, the site needed to feel warm and credible rather than polished in a generic insurtech way.","The bilingual strategy was not translation-first. English and Spanish content were shaped as parallel voice systems so each audience path felt intentional.","I treated the live site, not a static design deck, as the review artifact. That changed client feedback quality because the client evaluated a working experience on real devices."],"reflections":[{"title":"AI is best at compression, not authorship.","body":"The biggest gain came from compressing research synthesis, first-draft copy, and code scaffolding. Brand judgment, hierarchy, and trust signals still needed a designer making the calls."},{"title":"Localization is a design decision.","body":"The Spanish experience needed cultural adaptation, not literal translation. That changed tone, phrasing, and how reassurance showed up in the interface."},{"title":"A live product changes review quality.","body":"Showing the client a working site instead of frames made feedback faster and more grounded because they evaluated the real experience rather than imagining it."}],"nda_notice":null,"password":null,"external_link":null,"content_blocks":[{"id":"team-context","type":"custom","title":"Team","body":"I ran the engagement as a solo delivery across seven roles: UX/UI design, brand strategy, content strategy and writing, product ownership, development, QA, and bilingual localization. The client stepped in at final decision points rather than participating in every intermediate review."},{"id":"situation","type":"custom","title":"Situation","body":"Protecta is an independent health and life insurance advisory serving multicultural US families in English and Spanish. Their value is human-led, year-round guidance, the opposite of the call-center feeling common in the category.\n\nThey already had strong word-of-mouth momentum and a referral model that pays cash incentives, but they had no brand system, no website, and no content architecture to explain that value clearly online."},{"id":"task","type":"custom","title":"Task","body":"Deliver a full branded bilingual website, including homepage, internal pages, content strategy, brand system, component structure, accessibility QA, and live deployment.\n\nThe site needed to explain the referral program, communicate trust quickly, and give prospects a low-friction path to contact the advisors through WhatsApp."},{"id":"research","type":"custom","title":"Research","body":"I grounded the work in the 2026 Hispanic Insurance Growth Blueprint, client questionnaire, and advisor interviews—focusing on ACA, life, and digital acquisition. Advisor input surfaced recurring objections, trust concerns, and family questions.\n\nAI accelerated research synthesis, working definitions, and analysis of bilingual patterns and positioning gaps. I turned those insights into campaign decisions across audience, message, channels, and measurement, validated outputs against source material, and made the final brand and product calls."},{"id":"actions","type":"custom","title":"AI alignment","body":"I structured the work as an AI-augmented production pipeline with human judgment at each handoff. Claude and NotebookLM accelerated ideation, research synthesis, and first-draft copy.\n\nClaude Design created the initial visual direction; I then selected and refined the strongest ideas in Figma. With Figma AI, I built the reusable component library and its variants before using it as the reference for the coded interface. Codex and Claude Code accelerated implementation, while Storybook documented the implemented components and supported accessibility QA."},{"id":"impact","type":"results","title":"Result","body":"The outcome pairs a launch-ready bilingual website with an educational campaign designed to make medical coverage understandable and actionable for families. In its first 28 days, the campaign built meaningful organic discovery, interaction, and traffic from an audience that was almost entirely new to the page.","payload":{"rows":[{"metric":"Content views","value":"3.3K"},{"metric":"Unique viewers","value":"1,436"},{"metric":"Content interactions","value":"129"},{"metric":"Link clicks","value":"34"},{"metric":"Facebook visits","value":"55"},{"metric":"Net new follows","value":"+12"}],"insights":["Reporting period: July 10-August 6, 2026 (28 days).","98% of views came from non-followers, showing the educational creative reached well beyond the existing audience.","115 of 129 content interactions (89%) came from non-followers, reinforcing that the campaign generated engagement from new audiences rather than only the page's current followers.","The initial reach goals were exceeded: Facebook reached 1.5K against a goal of 208 (707%), while Instagram reached 567 against a goal of 169 (336%).","The reporting chart shows the strongest gains after the scheduled August rollout, an early signal that the organized bilingual publishing cadence is working."],"projected":["Connect link clicks and WhatsApp inquiries to a lead source so the next reporting cycle can measure qualified conversations and conversion, not only awareness.","Continue the bilingual content cadence around seasonal family-health moments and compare formats, messages, and posting times.","Replace stock placeholders with a real photo and video shoot featuring the advisors."]}}]}$case_en0$::jsonb
from public.case_studies
where slug = 
on conflict (case_study_id, locale) do update
set payload = excluded.payload;

insert into public.case_study_locales (case_study_id, locale, payload)
select id, , $case_en0${"slug":"reversetech","status":"published","featured":false,"order":7,"title":"Reverse Health Funnel Optimization & A/B Testing","company":"Reverse Health","client_context":"Paid search acquisition funnel","role":"Sr. Product Designer","year":2026,"duration":"Strategy and funnel analysis","industry":"Health & Fitness / Growth Funnel","tagline":"A growth case study turning funnel insights into testable design solutions.","tags":["Growth","UX Research","Product Design","Paid Acquisition","Funnel Optimization"],"filters":["UX Research","Product Design"],"tools":["Figma","Google Ads","Analytics","Miro","Notion"],"images":{"cover":"/images/projects/Reversetech/thumbnails/project-list-card-reversetech.svg","hero":"/images/projects/Reversetech/figma-screen.png","gallery":[]},"client_logos":[],"metrics":[],"team":["Growth team","Paid acquisition stakeholders","Product designer","Analytics partners"],"my_role":["Funnel Data Interpretation","UX & Conversion Problem Identification","Paywall Experiment Design","Testable Design Solution Framing"],"problem":{"admin_pain_points":["The funnel was converting at only 0.63% end to end, creating pressure to optimize quickly without clear evidence about where the real breakdown occurred.","Because the experience contained 44 steps, the team could easily default to the most visible explanation, that the quiz was simply too long, without first proving whether that was the dominant problem."],"user_pain_points":["Most visitors were arriving cold from Google Ads, so every step had to justify why they should keep going before enough trust had been built.","The middle of the funnel contained 37+ quiz steps, making it easy to assume the interaction cost itself was pushing users out.","Without a sharper diagnosis, any redesign risked polishing the middle while ignoring weaker parts of the funnel before or after it."]},"constraints":[],"methodology":{"name":"Funnel Diagnosis","steps":[{"step":1,"label":"Map","description":"Documented the full funnel from Google ad click through the 44-step quiz to purchase, identifying where the team believed friction was highest."},{"step":2,"label":"Question","description":"Challenged the default assumption that the long middle was the primary issue, reframing the problem as a funnel-level diagnosis instead of a step-count complaint."},{"step":3,"label":"Break down","description":"Separated the experience into acquisition promise, entry experience, quiz progression, and post-quiz transition so each part could be evaluated on its own terms."},{"step":4,"label":"Prioritize","description":"Focused the team on identifying which section of the funnel was truly leaking intent before committing to a redesign direction."},{"step":5,"label":"Frame next moves","description":"Defined the core problem statement the next design phase should solve instead of assuming the answer was to shorten the quiz."}]},"design_strategy":["The Enter Email step was selected for the design proposal based on its position as the second-largest in-funnel drop-off and one of the most critical moments to lose users. The main issue is a weak value exchange: users are asked to give their email and attention before clearly seeing what they will receive. As a result, the step feels more like lead capture than part of the personalized plan experience, and this is the proposed design solution.","Hypothesis 3","To reduce friction, the pages before email should better prepare users by showing progress, reinforcing why each question matters, and previewing the value of the final plan.","Adding trust signals, visible progress, app previews, and more relevant imagery would also make the ask feel safer and more connected to the product."],"reflections":[{"title":"The obvious problem is not always the real one.","body":"A long quiz is easy to blame because it is visible. That does not automatically make it the highest-leverage place to intervene."},{"title":"Cold traffic changes the standard.","body":"Visitors arriving from Google Ads have not earned much trust yet, so every part of the funnel has to work harder than it would in a warm audience context."},{"title":"Diagnosis is design work.","body":"Before changing layouts or reducing steps, the team needed a sharper understanding of where intent was actually breaking down."}],"nda_notice":"Some funnel details are summarized for portfolio use, but the structure, traffic context, and conversion problem reflect the real engagement.","password":null,"external_link":null,"content_blocks":[{"id":"overview","type":"overview","title":"Project Overview","body":""},{"id":"team-context","type":"custom","title":"Team","body":"I worked across growth and product conversations to help frame the real problem before design effort was spent in the wrong place. The work required alignment between acquisition thinking, funnel behavior, and user experience diagnosis."},{"id":"situation","type":"custom","title":"Situation","body":"Reverse Health was running a 44-step quiz funnel that sold a calisthenics program for women. End to end, the funnel was converting at 0.63%.\n\nTraffic was mostly cold paid search, with a typical visit beginning from a Google ad. Inside the team, the most intuitive explanation was that the long quiz middle, more than 37 steps, had to be where users were dropping."},{"id":"task","type":"custom","title":"Task","body":"The scope of the work centered on funnel diagnosis and design improvements, paywall experiment design, and competitor pattern extraction.\n\nMy role was to interpret funnel data, identify UX and conversion problems, and translate those insights into concrete, testable design solutions inside a performance-driven product environment."},{"id":"task-1","type":"custom","title":"Task 1","body":"Rather than treat every step as equal, I read all 44 and picked 3 to examine, balancing churn, user volume, and downstream influence. Then for each I dug into two questions: why it performs the way it does, and what user behavior, friction, or clarity issue explains the data.","payload":{"heading":"Funnel diagnosis & design improvements","table":[{"step":"31. age","churnCount":"7","churnPercent":"0.13%","userCount":"5,403","remainingPercent":"18.03%","dotColor":"#5ca95c"},{"step":"4. Main goal","churnCount":"224","churnPercent":"3.20%","userCount":"6,784","remainingPercent":"22.64%","dotColor":"#ffd45c"},{"step":"34. enter email","churnCount":"1,156","churnPercent":"21.62%","userCount":"4,190","remainingPercent":"13,99%","dotColor":"#ff2d2d","tag":"Design pick"}],"analyses":[{"title":"31. Age Step - Good Performance","body":"A clear, low-effort step. By this point abandoning the flow would feel wasteful, so users push through. The cognitive and emotional load is minimal, there's no financial decision attached, and most people understand that age matters in a health plan.","consideration":"Age is asked twice, on the landing and again at step 31. Testing it on a single step could cut effort and shorten the funnel.","image":"/images/projects/Reversetech/age.png"},{"title":"4. Main goal - Regular Performance","body":"The single-select option keeps it light and avoids decision overload for users. The friction is more subtle: this is the moment the user tells the product what outcome they want, so naming one goal carries emotional weight. A hypothesis, based on research, is that selecting a goal adds weight and that can feel like pressure, especially when the options don't fully align with the user or they haven't decided yet.","consideration":"Test a version with different content options, and add a \"Help me choose the right goal\" choice. Also reduce the number of steps before this question, so users reach their goal-setting moment sooner, while intent is still high.","image":"/images/projects/Reversetech/goal.png"},{"title":"34. Enter Email - Bad Performance","body":"This is the second biggest in funnel leak, and it's the worst possible place to lose people. At this point users can't yet see the value of the product, so asking for an email without explaining the benefit can feel like a marketing capture step rather than part of the personalized plan experience.","consideration":"Some users also sense the paywall coming. Handing over an email right before a likely payment ask makes the wall feel closer, so a chunk bail preemptively.","image":"/images/projects/Reversetech/email.png"}]}},{"id":"cta-variants","type":"custom","title":"CTA Variant","body":"The content on the email step does not feel personalized enough to make users believe a custom result is being built for them. The email page should reconnect them to their goal, preview what they will receive, and use outcome-based copy.","payload":{"variants":[{"label":"Variant 1","title":"See my personalized plan","body":"Makes the offer more specific by naming the Calisthenics plan directly. The hypothesis is that a clearer product label can make the email step feel more credible and less like generic lead capture.","imageSrc":"/images/projects/Reversetech/cta-variant-1.svg"},{"label":"Variant 2","title":"Get my calisthenics plan","body":"Presents the email ask in a slightly cleaner way. It tests whether reducing extra phrasing around the field makes the step feel faster while still giving users enough confidence to continue.","imageSrc":"/images/projects/Reversetech/cta-variant-2.svg"},{"label":"Variant 3","title":"Unlock my personalized plan","body":"Is the most stripped back. It relies on the personalized Calisthenics headline to do most of the persuasion.","imageSrc":"/images/projects/Reversetech/cta-variant-3.svg"}]}},{"id":"content-variants","type":"custom","title":"Content Variant","body":"By this point, users have invested time in the quiz but still have not seen the product's value clearly. Because progress is not visible, the funnel can feel longer than necessary, creating fatigue even when each screen is simple. This makes the email request feel abrupt instead of earned.\n\nAs a result, the step feels more like lead capture than part of the personalized plan experience, and this is the proposed design solution. For the purpose of this task, I selected Variant 3 as the final design solution, but I think a good approach would be to A/B test a few ideas.","payload":{"variants":[{"label":"Variant 3","title":"Variation: Category, Headline, Subtitle and Help Text","body":"Introduces energetic results-focused message and ties the plan to a concrete fitness outcome. It is more motivational than the others, but it depends on strong relevance.","imageSrc":"/images/projects/Reversetech/content-variant-3.svg"},{"label":"Variant 2","title":"Category, Headline, Subtitle and Help Text","body":"Keeps the plan-ready framing and pairs it with a direct no-spam reassurance. It is the safest content variant because it clarifies what the user gets while lowering privacy anxiety without adding too much extra explanation.","imageSrc":"/images/projects/Reversetech/content-variant-2.svg"},{"label":"Variant 1","title":"Category and Headline","body":"Personalizes the headline based on the user’s selected goal. It makes the outcome feel relevant and tailored, while keeping the email step connected to what the user already chose. The tradeoff is that it narrows the promise earlier, so the main goal selected needs to be here to keep the user's motivations.","imageSrc":"/images/projects/Reversetech/content-variant-1.svg"}]}},{"id":"impact","type":"results","title":"Impact","body":"I translated funnel evidence into prioritised, testable designs for the paywall conversion gap. The launched winning variant increased end-to-end conversion from 0.63% to 0.77%: a 0.14 percentage-point increase, or a 22% relative lift, equivalent to 14 additional purchases per 10,000 qualified visits.","payload":{"rows":[],"insights":["The quiz middle felt like the problem because it was long and highly visible.","Cold paid search traffic raised the cost of every commitment in the funnel, not just the quiz steps themselves.","The most important outcome of this phase was reframing the work from \"shorten the quiz\" to \"diagnose the real bottleneck first.\""],"opportunities":["Compare drop-off and intent quality between the landing entry, the quiz middle, and the post-quiz purchase transition.","Test whether the ad promise and landing expectation are aligned well enough for cold search traffic before asking users to commit to a long flow.","Identify which moments in the quiz earn momentum and which ones merely add interaction cost."]}},{"id":"sources","type":"custom","title":"Sources","body":"","payload":{"sources":[{"title":"Nielsen Norman Group — \"Progress Indicators Make a Slow System Less Insufferable\"","url":"https://www.nngroup.com/articles/progress-indicators/","description":"Supports progress feedback reducing uncertainty and keeping users moving. Caveat: this NN/g piece is about system and wait-time progress, not multi-step counters, so it works best paired with the goal-gradient research below for the step-count point specifically."},{"title":"Baymard Institute — \"Checkout Flows Average 5 Steps and 11+ Form Fields\"","url":"https://baymard.com/blog/checkout-flow-average-form-fields","description":"Supports unifying questions over just splitting steps: the number of form fields users must manage matters more to checkout UX than the number of steps, and most flows can drop to 6 to 8 fields."},{"title":"The Manifest — \"6 Steps for Avoiding Online Form Abandonment\"","url":"https://themanifest.com/web-design/6-steps-avoiding-online-form-abandonment","description":"Used for the stat that 27% of users abandon a form because it is too long, and once they abandon, they rarely return. Caveat: this is a 2018 survey of 502 people, so I treat it as dated."},{"title":"Nunes & Drèze (2006), Journal of Consumer Research — \"The Endowed Progress Effect: How Artificial Advancement Increases Effort\"","url":"https://academic.oup.com/jcr/article-abstract/32/4/504/1787425","description":"The exact origin of the term \"endowed progress effect\": people given artificial advancement toward a goal show greater persistence toward reaching it."},{"title":"Kivetz, Urminsky & Zheng (2006), Journal of Marketing Research — \"The Goal-Gradient Hypothesis Resurrected\"","url":"https://journals.sagepub.com/doi/abs/10.1509/jmkr.43.1.39","description":"Supports the claim that people accelerate effort as they get closer to a reward. I use this when I reference the goal-gradient effect.","secondaryTitle":"Columbia Business School summary","secondaryUrl":"https://business.columbia.edu/insights/chazen-global-insights/goal-gradient-hypothesis-resurrected-purchase-acceleration"},{"title":"IBM Carbon Design System — Progress indicator, usage guidelines","url":"https://carbondesignsystem.com/components/progress-indicator/usage/","description":"An authoritative design-system reference for showing users where they are: dividing the end goal into smaller subtasks increases the sense of completeness, and keeping users informed of where they are gives them a sense of control."},{"title":"WebAIM Million 2025 report","url":"https://webaim.org/projects/million/2025","description":"Used for the accessibility angle on the email field: home pages averaged 6.3 form inputs, and 34.2% of those inputs were not properly labeled. Note: the 48% figure floating around secondary sources is the share of homepages with at least one unlabeled input, which is a different metric."},{"title":"HubSpot — \"10 Form Conversion Optimization Tips\"","url":"https://blog.hubspot.com/marketing/optimize-conversion-forms","description":"From HubSpot's analysis of 40,000+ landing pages: buttons labeled \"Submit\" had lower conversion rates, and 3-field forms converted best with a drop-off after that. I use this for the \"outcome copy beats continue\" and \"keep the ask minimal\" points."}]}}]}$case_en0$::jsonb
from public.case_studies
where slug = 
on conflict (case_study_id, locale) do update
set payload = excluded.payload;

insert into public.case_study_locales (case_study_id, locale, payload)
select id, , $case_en0${"slug":"calendar-keeper","status":"published","featured":false,"order":8,"title":"Calendar Keeper","company":"HRS","client_context":"HRS","role":"Sr Product Designer","year":2026,"duration":"Independent AI-assisted discovery sprint","industry":"Healthcare / Practice Management SaaS","tagline":"AI-assisted product discovery for clinical scheduling—turning resource dependencies, outages, and compliance constraints into a phased product strategy.","tags":["Healthcare","Product Strategy","UX Research","Design Thinking","AI Product","Market Research"],"filters":["Healthcare","Product Strategy","AI Product"],"tools":["Claude AI","Gemini","NotebookLM","ChatGPT","Codex"],"images":{"cover":"/images/projects/calendar-keeper/thumbnails/calendar-keeper-cover.png","hero":"/images/projects/calendar-keeper/hero/calendar-keeper-hero.png","gallery":[]},"client_logos":[],"metrics":[],"team":["Product strategist","UX researcher","Healthcare domain experts","AI research partners"],"my_role":["Sr Product Designer"],"problem":{"admin_pain_points":["Clinical staff (MFAs, solo doctors) spend hours per day managing interruptions, double-bookings, and manual calendar checks instead of patient care.","German medical assistants handle TI-mandated tasks (e-prescriptions, KIM messaging, ePA) on top of scheduling for multiple practitioners; TI failures affect them directly.","Calendar sync failures create silent desync or full-day blocks, turning technical hiccups into operational crises with no visible recovery path.","Data sovereignty concerns are regulatory requirements (GDPR, BSI C5, German §203 StGB), not nice-to-haves."],"user_pain_points":["Returning patients trying to rebook or manage appointments have no fast self-service path, forcing them to call—the exact mechanism that floods staff.","Patients have no visibility that their health data stays within Europe, eroding trust in a market where data sovereignty is a regulatory mandate.","Generic scheduling platforms treat every booking as an interchangeable time slot and don't model the dependencies (room, equipment, practitioner, prep) that clinical workflows require."]},"constraints":["Zero network liquidity at the first clinic; waitlist and backfill algorithms need history to work.","Complex regulatory environment: France and Germany have different staffing models (5% of French GPs have assistants vs. German MFAs managing 3-19 practitioners).","High switching friction; 44.8% of German practices fear data won't migrate cleanly, suppressing demand even from dissatisfied users.","Competitor incumbency is different by market: Doctolib dominates France (23.2% PMS share); Germany shows Doctolib at 9 months in, leaving a narrow window."],"methodology":{"name":"Design Thinking","steps":[{"step":1,"label":"Empathize","description":"Problem discovery, user interviews, affinity mapping, and competitive market research"},{"step":2,"label":"Define","description":"Persona synthesis, affinity-map insights, and root-cause problem statements"},{"step":3,"label":"Ideate","description":"How-might-we questioning, hypothesis testing, and strategic alignment"},{"step":4,"label":"Prototype","description":"Phased product strategy, competitive positioning, and go-to-market sequencing"}]},"design_strategy":["Reclassify data sovereignty and MFA-first positioning as entry requirements, not differentiators; the real defensible advantage is resource-aware scheduling that doesn't break when infrastructure does.","Build the initial release around core booking with resource dependencies (room, equipment, practitioner, prep), not backfill—backfill needs a waitlist with history to be useful, which doesn't exist on day one.","Design degraded mode explicitly: when sync fails, show 'not synced' as a visible state, create a reconciliation queue, and allow appointments to be created locally with identity pending verification—turning a crisis into a known condition.","Germany-first GTM is evidence-based: Doctolib already owns France (23.2% share); Germany is 9 months into its PMS push (Nov 2025), leaving a narrow, measurable window.","Migration risk is the adoption blocker, not features; a credible, demonstrable data-migration path may matter more than calendar polish."],"reflections":[{"title":"Competition is real, but not where you'd expect.","body":"Doctolib has already won France; Samedi is shipping our claimed differentiators in Germany. The honest insight is that we need to find an angle competitors haven't occupied yet—which turns out to be degraded-mode reliability and honest about what's Phase 1 vs. Phase 2."},{"title":"Market structure changed the strategy.","body":"France/Germany staffing differences are not just flavors of the same problem. They need two real product variants, two go-to-market approaches, and two different win narratives. One-size-fits-all would fail."},{"title":"Data sovereignty is table stakes now.","body":"GDPR, BSI C5, and EU AI Act compliance are regulatory, not differentiating. Consent architecture and transparency matter more than hosting location, because every competitor claims the same thing."},{"title":"Constraints forced the better decision.","body":"Knowing we can't support backfill on day one (no liquidity) forced us to ask what actually works at the first appointment of the first clinic. The answer—resource-aware core booking—is more defensible than a wishlist feature."}],"nda_notice":"This is an early-stage strategy document and design thinking process. Client details and competitive data are anonymized or aggregated per market. The methodology and findings reflect real market research and user discovery.","password":null,"external_link":null,"content_blocks":[{"id":"overview","type":"overview","title":"Project Overview"},{"id":"design-thinking-facilitation","type":"custom","title":"Design Thinking Facilitation","body":"Structured the discovery process across five phases—Empathize, Define, Ideate, and Prototype—using design thinking methodology to move from unstructured problems to actionable strategy. Each phase built on the previous, creating a chain of validated insights rather than assumptions."},{"id":"user-research-synthesis","type":"custom","title":"User Research & Synthesis","body":"Conducted discovery across two distinct markets (France and Germany), uncovering nine distinct problem statements from different user perspectives: the Calendar Keeper (solo doctor vs. MFA), the returning patient, and the system itself. Synthesized qualitative findings into personas, affinity maps, and root-cause analyses that revealed the structural gaps competitors miss."},{"id":"competitive-intelligence","type":"custom","title":"Competitive Intelligence","body":"Performed rigorous market analysis covering incumbent PMS vendors, new entrants, and market dynamics. Identified that Doctolib already owns France (23.2% PMS share), Samedi occupies claimed differentiators in Germany, and migration risk—not features—is the real adoption blocker. This research reframed strategy and go-to-market approach."},{"id":"solution-strategy","type":"custom","title":"Solution Strategy","body":"Translated research into a phased delivery approach: core booking with resource dependencies (Phase 1), degraded-mode reliability (Phase 1), and onboarding/backfill (Phase 2). Repositioned from claimed differentiators (sovereignty, MFA-first) to a defensible angle: resource-aware scheduling that doesn't break when infrastructure does. Recommended Germany-first GTM based on market evidence."},{"id":"methodology","type":"custom","title":"Methodology: Design Thinking","body":"The discovery process followed a structured design thinking approach across four phases, augmented with AI tools and rigorous market research.","payload":{"phases":[{"phase":"Empathize","description":"Problem discovery, user interviews, affinity mapping, and competitive market research"},{"phase":"Define","description":"Persona synthesis, affinity-map insights, and root-cause problem statements"},{"phase":"Ideate","description":"How-might-we questioning, hypothesis testing, and strategic alignment"},{"phase":"Prototype","description":"Phased product strategy, competitive positioning, and go-to-market sequencing"}]}},{"id":"empathize-intro","type":"custom","title":"Empathize: Problem Discovery & Market Research","body":"The empathize phase combined direct user discovery with rigorous competitive intelligence to understand the real shape of the market and the users' unmet needs."},{"id":"problem-statements","type":"custom","title":"Problem Statements","body":"Nine distinct problem framings across different user roles and markets emerged from research.","payload":{"problems":["The Calendar Keeper needs the schedule to reflect reality without manually re-checking it, because interruptions all day—calls, changes, no-shows—otherwise cost clinical time or cause double-booking.","The German MFA needs to complete TI-mandated tasks in fewer clicks and with fewer failure points, because half of German practices hit TI issues weekly, and those failures land on the MFA, not the doctor.","The German MFA/MVZ needs to triage and delegate scheduling across many practitioners from one view, because a single MVZ can employ up to 19 MFAs coordinating calendars that a single-doctor interface was never built to handle.","The French solo doctor needs routine calls handled without leaving the exam room, because 30% of calls already go unanswered, and every one is either a lost patient or an interrupted consultation.","Real-time, trustworthy availability serves the Calendar Keeper first, because a stale calendar is a double-booking risk for staff before it's a bad search experience for a patient.","The Calendar Keeper needs to schedule lower-acuity visits as phone or video rather than defaulting everyone into an in-person slot, because it protects in-person capacity for visits that actually need it.","Both the Calendar Keeper and the returning patient need visible proof that health data stays in Europe, because sovereignty is a named trust-breaker and a 2026 compliance requirement.","The returning patient needs to rebook or manage an existing appointment quickly using identity already on file, because deflecting that routine call is the entire mechanism by which the Calendar Keeper's workload actually drops.","A returning patient occasionally booking for a named dependent needs a minimal, manual-entry path, not full account linking."]}},{"id":"user-needs","type":"custom","title":"User Needs: Provisional User Groups","body":"Six distinct user groups emerged from research, each with specific needs, pain points, and consequences of error. These are provisional groupings, not final personas.","payload":{"groups":[{"group":"Patients — new & existing","goal":"Make an appointment with low effort and minimal disclosure of personal data.","pain_points":["Abandon booking when forms ask for non-essential info, or in France when INS (Identifiant National de Santé) requires exact birth-registration details — high friction at registration.","Frustrated by technical failures: blank-page errors, forced logouts, inability to screenshot/copy confirmation info.","In Germany, Double Opt-In (email/SMS) can leave a slot unconfirmed and effectively lost.","Frustrated when 'no online appointments available' makes the tool feel like wasted effort.","Erosion of trust when a listed language capability (e.g., 'speaks English') doesn't hold up in person — accuracy of practitioner metadata matters for safety, not just satisfaction.","Distrust of platforms perceived to route consultation notes or data to non-EU AI providers or third parties — this is a trust-driven abandonment cause."],"consequence":"Missed/duplicate bookings, abandoned funnel, or (in the language-mismatch case) a care-quality risk.","jtbd":"When I need to see a doctor, and I'm unsure of the process, I want to find and confirm a real, available slot without giving up more information than necessary, so I can trust the appointment will actually happen."},{"group":"Caregivers / people booking for someone else","goal":"Manage appointments for a dependent (child, elderly parent) as smoothly as for themselves.","pain_points":["One-third of French appointments are booked for a relative; ~46% of patients have a linked relative account — this is not an edge case, it's a core flow.","Birthdate entry via month-by-month dropdown scrolling is a specific, named friction point for this group.","Permissions implication: the product needs a first-class 'manage on behalf of' model, not a bolt-on."]},{"group":"Older / lower-digital-literacy patients","goal":"Access appointment booking with appropriate support for their technology comfort level.","pain_points":["5.9M French Doctolib users are 65+ (scale signal), but German patients 80+ are described as 'overwhelmed' by digital tools, many without smartphones/PCs — this is a market-specific gap, not the same problem in both countries.","Visually impaired users need accessible booking flows; all patients need clarity on physical accessibility (wheelchair access) of the practice itself."],"consequence":"Exclusion from self-service, which pushes load back onto phone lines — directly connects to the receptionist pain point."},{"group":"Receptionists / Medical Assistants (MFAs)","goal":"Keep the schedule accurate with minimal manual rework, while handling constant interruptions.","pain_points":["~30% of calls to doctors go unanswered; routine calls (insurance checks, rescheduling) bury the front desk.","German MFAs are frustrated by click-heavy TI workflows (KIM messaging, e-prescriptions) and by card-reader/system crashes after updates.","Structural difference: in Germany, the MFA is a power user — 3 years trained, performs clinical tasks (blood draws, dressings) and admin (booking, invoicing); average 3.4 per solo practice, up to 19 in MVZs. In France, only ~5% of GPs employ an MFA at all, and tasks are mostly administrative."],"design_implication":"The receptionist is not one persona — Germany needs an assistant-centric, delegation-capable interface; France needs the doctor to remain the central actor. This is one of the sharpest tensions in the whole project."},{"group":"Doctors / clinicians","goal":"Maximize clinical time, minimize administrative drag.","pain_points":["Structural difference in how doctors use time: Germany — 9.8 contacts/year, ~8 min/visit, high patient turnover, 'one-click' documentation need. France — 5.9 contacts/year, 16–18 min/visit, favors longitudinal notes and longer-form UI.","~10 hours/week lost to administrative bottlenecks (cited as the pain point Doctolib is attacking with AI call-handling)."],"consequence":"Double-booking or lost time directly reduces billable clinical capacity — this group is revenue-sensitive to scheduling errors in a way patients aren't."},{"group":"Clinic managers / administrators, and internal CX/support teams","status":"🔴 Research gap","note":"No direct evidence yet. The source material speaks to receptionists and doctors but not practice owners/managers or internal implementation teams. Flagged as an open research need rather than inventing needs."}]}},{"id":"user-needs-context","type":"custom","title":"Context: Regulatory, Operational & Competitive Landscape","body":"User needs cannot be understood without the regulatory, workforce, and competitive context that shapes them.","payload":{"regulatory":{"title":"Regulatory & Governance Context","france":"Centralized — State + Assurance Maladie set fees, certifications, and negotiations nationally. HDS v2.0: mandatory health-data hosting certification. Transition to V2.0 by May 16, 2026; September 2026 sovereignty rules require EEA-only hosting and disclosure of non-EU legal exposure (e.g., US CLOUD Act).","germany":"Decentralized — corporatist bodies (G-BA, regional KVs) control market access; Bedarfsplanung restricts where/how physicians can even set up practice. Telematic Infrastructure (TI): mandatory closed network; ePA integration deadline October 1, 2025; authentication via physical SMC-B/eHBA cards. 50% of German doctors report weekly TI technical issues — a stated competitive opening for a more stable entrant."},"workforce":{"title":"Workforce & Operational Context","gp_density":"France — GP-heavy (107/100k) and primary-care-volume-oriented. Germany — specialist-heavy (117/100k), with 2x the ambulatory surgeons and ~3x the gynecologists — meaning Germany's scheduling needs skew toward complex resource booking (rooms, equipment, surgical blocks), not just time slots.","consultation_rhythm":"France: 5.9 visits/year, 16–18 min/visit, favors longitudinal notes. Germany: 9.8 visits/year, ~8 min/visit, high patient turnover, 'one-click' documentation need. This drives fundamentally different information-density needs in the booking and documentation UI."},"competitive":{"title":"Competitive Landscape","incumbent":"Doctolib is the dominant incumbent, having moved from booking tool to full practice-OS, launching its German PMS in late 2025, with AI call-handling and Adyen-based embedded payments.","trust_gaps":"MFA workload from unsecured requests, and a broader 'data sovereignty' trust crisis — named as a specific opening for a sovereign/privacy-first entrant.","pricing":"Samedi ~€35–59/user; Doctolib ~€139/practitioner."},"business":{"title":"Business Context — Explicitly Unresolved","note":"GTM sequencing (France-first vs. Germany-first) is not decided. This matters for empathize scope: if we don't know which market launches first, we should keep our priority workflow choice defensible in both markets rather than optimizing narrowly for one. Pricing/bundling model with the existing suite is undefined."}}},{"id":"competitive-analysis","type":"custom","title":"Competitive Research: Three Market-Changing Findings","body":"Market analysis revealed that conventional assumptions about our position were incorrect.","payload":{"findings":[{"title":"⚠️ Doctolib has already won the French PMS market","body":"Doctolib is the most-used GP practice-management software in France as of March 2026, with 23.2% of electronic care-claim transmissions, ahead of Weda (14.0%), Medistory (10.1%) and HelloDoc (8.1%). It went from 0% to 23.2% in five years — and did it without acquisitions, purely by attaching software to its booking platform.\n\nThis inverts our earlier framing. In France, Doctolib now holds both patient distribution and practice distribution. Our 'we're strong where they're weak' argument does not hold."},{"title":"🔵 In Germany, the same move is barely underway — and that's a narrow, dated window","body":"Doctolib's German PVS launched in November 2025, initially only for GPs, pediatricians and gynecologists. In the Zi 2026 evaluation, Doctolib had insufficient sample size to produce valid usability, NPS or error-rate data.\n\nRead together with the France finding, this is the strongest empirical argument for Germany-first GTM — a decision our documents listed as undecided. France is a market Doctolib has already taken; Germany is one it started taking nine months ago."},{"title":"⚠️ Samedi occupies our claimed differentiators","body":"Samedi is a Berlin-based SaaS platform used by more than 48,000 doctors across roughly 10,000 institutions in the DACH region, offering online booking with a waitlist, dynamic resource planning, digital forms with e-signature and integrated payment — backed by EU-patented end-to-end encryption, TÜV certification and ISO 27001/9001.\n\nThat is resource-aware scheduling plus sovereignty positioning plus waitlist/backfill, already shipped, at scale. Two of our three claimed differentiators are occupied. Their real gaps: no public patient-search portal, per-doctor pricing that compounds for group practices, no free entry tier, and no self-service onboarding."}]}},{"id":"market-dynamics","type":"custom","title":"Market Dynamics: The Real Displacement Lever","body":"What actually drives switching is not satisfaction—it's switching barriers and migration risk.","payload":{"key_insight":"33.3% of German practices want to switch PMS (down from 44.4% in 2024). One in three is actively shopping. But the decline is not due to improved satisfaction; it's due to perceived switching barriers.","displacement_dynamics":[{"signal":"Practices wanting to switch PMS","figure":"33.3% in 2025 (down from 44.4% in 2024)","meaning":"Demand is suppressed, not satisfied"},{"signal":"Top blocker","figure":"44.8% fear data won't migrate cleanly","meaning":"Migration is the product problem, not features"},{"signal":"Switch motives","figure":"Usability (1st), fees (2nd), support (3rd)","meaning":"Usability is a design lever; incumbency has poor experience"},{"signal":"Post-switch outcome","figure":"83.9% report significant improvement","meaning":"Switching works, but people are switching to systems already rated poorly"}],"proof":"AxiSanté (CGM) fell from 16% in 2019 to under 0.2% by 2026 after end-of-support was announced. Incumbency collapses fast once trust breaks."}},{"id":"sovereignty-context","type":"custom","title":"Sovereignty Claims: Properly Tiered","body":"Data sovereignty is a live, contested issue—not a differentiator we can own.","payload":{"reality":"Doctolib uses AI from Google, Microsoft and Anthropic in its consultation assistant. Under scrutiny; allegations that patient data may be exposed to US tech providers. Doctolib denies misuse; OECD classifies it as a hazard rather than a realised incident. EU AI Act becomes applicable August 2, 2026.","honest_read":"The trust vector is real and currently active — but Doctolib's formal compliance posture is strong, and our own advantage would rest on consent architecture and transparency, not on hosting location. Hosting location is table stakes; every competitor claims it.","takeaway":"'We're the sovereign one' is not a defensible differentiator. 'We don't use your patients' data by default, and we can show you exactly what we do use' might be."}},{"id":"define-intro","type":"custom","title":"Define: Personas, Patterns & Root Causes","body":"The define phase synthesized research into persona models and identified the structural problems beneath the surface complaints."},{"id":"affinity-map","type":"custom","title":"Affinity Map: What Shapes the Primary Flow","body":"Research revealed deep structural differences that shape product architecture decisions.","payload":{"findings":[{"title":"France and Germany are staffed like two different professions","details":"GP density is 107/100k in France vs. 66/100k in Germany; consultation rhythm follows the same divide — 5.9 visits/year at 16–18 minutes in France, 9.8 visits/year at ~8 minutes in Germany. This is why the Calendar Keeper needs two real variants rather than one interface with a language toggle."},{"title":"The calendar has to be trustworthy, not just present","details":"Patients who search extensively and hit 'no appointments available' describe the tool as a waste of time. On the operations side, 81% of German practices report TI connector errors and 82% report failures reading the eGK card — meaning the calendar itself becomes unreliable before a patient ever sees it."},{"title":"The front desk is already underwater","details":"Roughly 30% of calls to doctors go unanswered. German MFAs specifically cite click-heavy TI workflows and card-reader failures as recurring stressors. The 10 hours/week lost to administrative work is exactly what competitors are targeting with AI call-handling."},{"title":"Data sovereignty is a trust condition, not a feature","details":"Trust breaks when consultation data appears to reach non-European AI models or third parties. This isn't segment-specific — it matters to the Calendar Keeper (compliance exposure) and the returning patient (trust) equally, and September 2026 rules make EEA-only hosting a requirement rather than a preference."}]}},{"id":"personas","type":"custom","title":"Proto Personas","body":"Two distinct user archetypes emerged, not language variations.","payload":{"primary":{"title":"The Calendar Keeper","description":"One role, filled by a different person depending on the market — whoever owns the schedule and needs it to be true without constantly re-checking it.","job":"When my schedule is interrupted all day by calls, changes, and no-shows, I want the calendar to always be true without me re-checking it, so I don't lose clinical time or double-book someone.","france":{"title":"Solo-practice doctor","details":"Runs the front desk personally, since only ~5% of French GPs employ an assistant. Sees patients for 16–18 minutes at a time and absorbs interruptions between consultations rather than delegating them. Needs routine calls (rescheduling, insurance questions) handled without leaving the exam room."},"germany":{"title":"MFA (Medizinische Fachangestellte)","details":"Clinically trained over three years, manages the calendar for multiple practitioners — 3.4 on average in a solo practice, up to 19 in a larger MVZ. Sees shorter, more frequent consultations (~8 minutes, 9.8 visits/year) and spends real time on TI-mandated tasks (KIM messaging, e-prescriptions, ePA). Roughly half of German practices report weekly TI technical issues, and those failures land on the MFA. Needs to triage and delegate across many practitioners from a single view."}},"secondary":{"title":"The Returning Patient","description":"A narrow, deliberately thin surface. Its only job is to let a patient who already has a record rebook, cancel, or manage an existing appointment without calling.","scope":"Occasionally includes booking for a named dependent, entered manually for that one appointment — not a saved, linked profile. Deliberately excludes new-patient identity verification, full linked-account management, and reporting/analytics in v1."}}},{"id":"root-causes","type":"custom","title":"Root Causes: What's Really Broken","body":"Research uncovered that the obvious problems mask deeper structural issues.","payload":{"q_a":[{"q":"What are the core problems?","a":"Generic scheduling platforms treat every booking as an interchangeable time slot. A clinic appointment often depends on a room, a piece of equipment, a specific practitioner, and prep time together, and no competitor architecture models that dependency because it was built demand-side (Doctolib's lineage). Second problem: when sync fails (IT outage, eGK reader down), most systems either silently desync or block the whole day, turning a technical hiccup into an operational crisis."},{"q":"What are the root causes?","a":"The dependency gap is structural, not a feature gap. It's baked into how the underlying data model was designed. The sync-failure problem is a design omission: no one designed for degraded mode, so failure has no visible state, no reconciliation path, and no safe default."},{"q":"What are stakeholder perspectives?","a":"The clinic evaluates resource-aware booking during the sales demo itself, not months in. The Head of CX cares about one distinction: does a sync failure become a support ticket or a full-blown crisis. Engineering's real risk is write access and schema quality on integration, and resource dependencies are exactly what exposes a bad sync."},{"q":"What are the current constraints?","a":"Zero liquidity at the first clinic (no history, no waitlist data), which rules out anything that needs a network effect to be useful on day one."}]}},{"id":"ideate-intro","type":"custom","title":"Ideate: How-Might-We & Strategic Questioning","body":"The ideate phase used structured questioning to move from problems to actionable hypotheses."},{"id":"hmw-questions","type":"custom","title":"How-Might-We Questions","body":"Five categories of questions scoped the solution space and tested assumptions.","payload":{"categories":[{"type":"Amplifying","example":"How might we amplify trust in the schedule the moment sync fails?","answer":"Make 'not synced' a visible, named state rather than a silent gap, so front-desk staff see degraded mode as a known condition, not an unexplained glitch."},{"type":"Removing","example":"How might we remove the full-day-block failure mode entirely?","answer":"Let appointments get created locally with identity pending verification when the eGK reader or IT fails, and queue them for reconciliation instead of halting the whole day's schedule."},{"type":"Exploring","example":"How might we explore what a reconciliation queue should feel like operationally?","answer":"Prototype it as a 1-2 screen flow (status badge, queue view) and test whether front-desk staff can act on it without training, since this is what gets demoed to the Head of CX."},{"type":"Questioning assumptions","example":"How might we challenge the assumption that 'data sovereignty' and 'MFA-first' are differentiators?","answer":"Reclassify both as entry requirements, not selling points. Every competitor already claims them, so leading with them wastes the differentiation slot that resource-aware scheduling can actually own."},{"type":"Unexpected resource","example":"How might we use the deferred backfill feature as evidence of judgment rather than as a gap to hide?","answer":"Frame it explicitly to the clinic: backfill needs a waitlist with history to have any input, and that liquidity doesn't exist in month one, so it's Phase 2 by design, not by oversight."}]}},{"id":"question-characteristics","type":"custom","title":"Question Characteristics: Testing Rigor","body":"The HMW set held up against four validity tests.","payload":{"tests":[{"test":"Scoped","description":"Each question is scoped to the two screens that actually ship (core booking, degraded mode), not a wishlist."},{"test":"Actionable","description":"They map directly to what gets built and demoed."},{"test":"Positively framed","description":"Around 'what does trustworthy degraded mode look like' rather than 'how do we hide our sync problem.'"},{"test":"Feasible","description":"None require a network effect or existing liquidity, which is why backfill sits outside this set entirely. Everything here works at the first appointment of the first clinic."}]}},{"id":"strategic-alignment","type":"custom","title":"Strategic Alignment","body":"Each question connects directly to user pain, business objective, and technical risk.","payload":{"alignment":[{"lever":"User pain","connection":"Front-desk staff lose confidence in the schedule the moment sync breaks silently. The removing and exploring questions target that directly."},{"lever":"Business objective","connection":"The sales-evaluation moment is the resource-aware core flow, so every HMW here either strengthens that flow or protects it from the failure mode that would undermine it during a demo."},{"lever":"Technical constraint","connection":"The questioning-assumptions HMW forces the team to test write access and schema quality early, since that's where a bad sync would surface first."}]}},{"id":"prototype-intro","type":"custom","title":"Prototype: Phased Product Strategy & Positioning","body":"The prototype phase translated discoveries into a concrete, sequenced go-to-market plan."},{"id":"solution-strategy","type":"custom","title":"Solution: New Hero Flow","body":"A three-layer approach that prioritizes what works on day one.","payload":{"layers":[{"tier":"Core (high fidelity)","name":"Appointment-type setup with resource dependency → booking that respects it","details":"Room + equipment + practitioner + prep, where generic platforms treat everything as time slots.","why":"Works with zero liquidity. It's useful at the very first appointment of the very first clinic. It's the real structural gap: competitors don't do this because their architecture was born on the demand side. It's the flow the clinic evaluates during the sale, not six months later. It tests the most dangerous technical assumption (write access and schema quality), because resource dependencies are exactly what a poor sync breaks."},{"tier":"Secondary (high fidelity, 1–2 screens)","name":"Degraded mode and conflict resolution","details":"Visible 'not synced' status, reconciliation queue, appointment created locally with identity pending verification, never a full-day block.","why":"Turns the sync-failure problem into a designed response instead of an empty claim. When IT or the eGK reader fails, the schedule stays reliable and operable. This is what the Head of CX wants to hear, because it's the difference between a ticket and a crisis."},{"tier":"Tertiary (low fidelity, Phase 2)","name":"Time-to-first-configured-schedule (onboarding)","details":"Wireframes documenting the setup flow without polish.","why":"Onboarding goes into scope, but as a wireframe. It doesn't need to be pretty; it needs to exist and be measured. Backfill moves to Phase 2 with explicit justification: backfill needs a waitlist with history to exist; we deferred it because in month 1 it has no input, and its value depends on liquidity this release doesn't create yet. This signals seniority: we know what matters first."}]}},{"id":"competitive-positioning","type":"custom","title":"Repositioning: What Actually Differentiates","body":"Reframe the narrative based on what competitors can't occupy.","payload":{"reframe":[{"claim":"Data sovereignty & MFA-first positioning","before":"Differentiators","after":"Entry requirements","reason":"Every competitor claims them; they don't set us apart."},{"claim":"Resource-aware scheduling","status":"Partially occupied","angle":"Samedi ships it, but the real defensible differentiator that remains is narrower and more honest"}],"defensible_differentiator":"Resource-aware scheduling that doesn't break when the infrastructure does. It's verifiable, it's measurable, and it doesn't depend on a network effect we don't have."}},{"id":"gmt-strategy","type":"custom","title":"Go-to-Market Strategy: Germany First","body":"Evidence-based market selection shifts from undecided to recommended.","payload":{"prior":"GTM sequence was undecided","evidence":"France is a market Doctolib has already taken (23.2% PMS share). Germany is one it started taking nine months ago (Nov 2025), with insufficient sample size for valid usability data. A narrow window, measurable, and favorable.","recommendation":"Germany-first GTM. Bring to stakeholder conversation as a recommendation with evidence, not as a design assumption."}},{"id":"strategic-recommendations","type":"custom","title":"Strategic Recommendations: What Changed","body":"Market research reshaped the initial scope and positioning.","payload":{"table":[{"prior":"Doctolib is a booking tool moving into PMS","status":"⚠️ False in France — it's #1 in PMS","action":"Rewrite the competitive slide"},{"prior":"GTM sequence undecided","status":"🔵 Evidence now favours Germany-first","action":"Bring as a recommendation to stakeholders"},{"prior":"Resource-aware scheduling is our differentiator","status":"⚠️ Samedi ships it at scale","action":"Necessary, not sufficient — reposition"},{"prior":"Sovereignty is our differentiator","status":"⚠️ Occupied by both rivals","action":"Shift to consent architecture + transparency"},{"prior":"Legacy instability is the wedge","status":"🔵 Confirmed and quantified","action":"Keep; strengthen with Zi data"},{"prior":"Three-layer architecture","status":"✅ Unaffected","action":"Keep"},{"prior":"Calendar Keeper primary user","status":"✅ Unaffected — Doctolib built its PVS in close collaboration with MFAs and doctors","action":"Keep; validates that the MFA is the right target"},{"prior":"—","status":"🆕 Migration risk as adoption blocker","action":"Add to initial requirements; possibly more decisive than any calendar feature"}]}},{"id":"new-constraints","type":"custom","title":"New Technical & Regulatory Constraints","body":"Market research surfaced compliance requirements not in the original brief.","payload":{"constraint":"Cloud PVS providers in Germany face §203(3–4) StGB, Art. 28 GDPR, §393 SGB V and BSI C5 attestation requirements — and a data-processing agreement alone does not remove the criminal-law professional-secrecy exposure.","requirement":"KBV conformity assessment and TI connection are mandatory for cloud systems too.","implication":"This is a cloud-native entry barrier none of our four project documents captured. Add to technical-constraints register."}},{"id":"market-tailwinds","type":"custom","title":"Market Tailwinds & Baseline Metrics","body":"Research confirmed and quantified key demand signals.","payload":{"german_infrastructure":["82% of practices report recurring problems reading the electronic health card (eGK)","81% report frequent TI connection errors","71% report regular difficulties creating e-prescriptions"],"patient_adoption":"64% of Germans have booked a medical appointment online at least once, up from 36% in 2023 — strong tailwind for the patient-facing side of the initial release."}}]}$case_en0$::jsonb
from public.case_studies
where slug = 
on conflict (case_study_id, locale) do update
set payload = excluded.payload;

