select id, , $case_es0${"slug":"benefits-enrollment","status":"published","featured":true,"order":4,"title":"Acceso de autoservicio y gestión de roles","company":"Paychex & Flock","client_context":"Paychex & Flock","role":"Diseñador de Producto Senior (Crecimiento y Monetización)","year":2025,"duration":"3 meses","industry":"BENEFICIOS / SAAS DE SEGUROS","tagline":"Sustituyó un flujo de trabajo manual por una plataforma centralizada y autogestionada, reduciendo el tiempo de procesamiento en un 72%.","tags":["BENEFITS / ENSURANCE SAAS","UX Research","IA","Interaction Design","Design Systems"],"tools":["Jira","Miro","Webex","Outlook","Copilot","Hotjar"],"images":{"cover":"/images/projects/benefits-enrollment/thumbnails/thumbnail-benefits.png","hero":"/images/projects/benefits-enrollment/hero/benefits-hero.png","gallery":["/images/benefits/figma-logo.png","/images/benefits/jira-logo.png","/images/benefits/miro-logo.png"]},"client_logos":[{"name":"Paychex","logo":"/images/c54fy.png"},{"name":"Flock","logo":"/images/flock-logo.png"},{"name":"IBX","logo":"/images/SNUZw.png"}],"metrics":[{"value":"72%","label":"Reducción en el tiempo de procesamiento","context":"procesamiento de beneficios"},{"value":"500+","label":"Empleados autogestionados","context":"sin tickets de TI"},{"value":"3 mo","label":"Diseño y entrega de extremo a extremo","context":"cronograma"}],"team":["Product Owner","Gerente de Programa","Analista de Negocio","Investigador","Equipo de desarrollo (12)","Gerente de UX","Líder de UX","Diseñador UX/UI","Arquitecto de Servicio","Scrum Master"],"my_role":["Investigación de Usuarios","Diseño UX/UI","Pensamiento de Producto","Narrativa"],"problem":{"admin_pain_points":["Los cambios en beneficios requerían ejecutar múltiples ciclos de nómina y una conciliación manual.","Los administradores no tenían una forma sencilla de agregar los datos de los empleados de todos los departamentos en un solo lugar.","Cuando se producían picos de inscripción, no existía un flujo claro de escalado o alerta."],"user_pain_points":["Añadir nuevos empleados requería tickets de soporte y esfuerzo de desarrollo manual.","Los datos debían recopilarse, validarse y enviarse entre equipos. Los cambios se seguían por correo electrónico.","No existía una gobernanza centralizada ni una estructura de permisos clara."]},"constraints":["Un cronograma muy ajustado.","Equilibrar los patrones existentes del producto con las necesidades de los usuarios sin alterar la experiencia."],"methodology":{"name":"Design Thinking","steps":[{"step":1,"label":"Empatizar","description":"Entrevistas con usuarios y sesiones con stakeholders"},{"step":2,"label":"Definir","description":"Definición del problema y mapeo de puntos de dolor"},{"step":3,"label":"Idear","description":"Flujos, arquitectura y wireframes"},{"step":4,"label":"Prototipar","description":"Pantallas de alta fidelidad y prototipos interactivos"},{"step":5,"label":"Probar","description":"Análisis con Hotjar tras el lanzamiento"}]},"design_strategy":["Definir la arquitectura y la lógica subyacentes antes de cambiar la interfaz.","Identificar qué partes del sistema funcionan bien y construir a partir de ellas.","Al no existir un sistema de diseño, la colaboración con el equipo de desarrollo garantizó que la interfaz final se mantuviera coherente en todo momento."],"reflections":[{"title":"La arquitectura antes que la interfaz.","body":"Invertir tiempo en mapear el modelo de permisos antes de diseñar las pantallas evitó retrabajos costosos. La lógica tenía que ser impecable antes de mover un solo píxel."},{"title":"Confianza a través de las restricciones.","body":"Trabajar sin un sistema de diseño exigió una colaboración estrecha con los ingenieros. Las sincronizaciones constantes mantuvieron la interfaz coherente y la entrega fluida incluso bajo presión de plazos."}],"nda_notice":"Partes de esta presentación, incluidas algunas pantallas y detalles del proyecto, han sido ocultadas o difuminadas debido a un acuerdo de confidencialidad firmado con el cliente. El trabajo mostrado es real; se omiten los detalles completos para proteger la privacidad del cliente.","password":null,"external_link":null}$case_es0$::jsonb
