insert into public.case_study_locales (case_study_id, locale, payload)
select id, , $case_es0${"slug":"nayya-ai-benefits","status":"published","featured":true,"order":1,"title":"Integración de Nayya","company":"Nayya","client_context":"Paychex a través de ITX Corp","role":"Diseñador de Producto Sr.","year":2025,"duration":"6 meses","industry":"Beneficios con IA / SaaS de RRHH","tagline":"Diseñó la integración de Nayya como herramienta de beneficios impulsada por IA, guiando a los empleados a elegir la cobertura que mejor se ajustaba a sus necesidades.","tags":["BENEFITS / ENSURANCE SAAS","UX Research","IA","Interaction Design","Design Systems"],"tools":["Figma","Jira","Miro","Webex","Outlook","Copilot","Hotjar"],"filters":["UX Research","Product Design","AI Product"],"images":{"cover":"/images/projects/nayya-ai-benefits/thumbnails/thumbnail-nayya-cover.png","hero":"/images/projects/nayya-ai-benefits/hero/nayya-hero.png","gallery":[]},"client_logos":[{"name":"Nayya","logo":"/images/bBw3A.png"},{"name":"Paychex","logo":"/images/c54fy.png"}],"metrics":[{"value":"307%","label":"TIR","context":"ROI proyectado, retorno estimado por el aumento en la contratación de planes (VAN $11.4M)."},{"value":"~115,500","label":"Beneficios Anuales","context":"Inscripciones completadas un 5% por encima del objetivo de 100K."},{"value":"67%","label":"Tasa de Conversión","context":"Usuarios que recibieron recomendaciones de Nayya ajustadas a sus necesidades y se inscribieron en un plan."}],"team":["Líder de UX","Diseñador de Contenido","Product Owner","Analista de Negocio","Líderes de Solución"],"my_role":["Estrategia UX","UX de Integración","Investigación de Usuarios","Pensamiento de Producto"],"problem":{"admin_pain_points":["Una integración embebida y fluida entre Flex y Nayya Choose no era viable dadas las limitaciones técnicas.","El equipo tenía que equilibrar el valor de negocio, las limitaciones técnicas y la confianza del usuario durante un proceso de toma de decisiones sensible."],"user_pain_points":["Los empleados necesitaban más apoyo a la hora de seleccionar beneficios y elegir una cobertura acorde a sus necesidades.","Los usuarios tenían que salir de Flex y acceder a Nayya Choose en una experiencia independiente.","La transición necesitaba una comunicación más clara, más contexto y señales visuales que hicieran que el cambio se sintiera intencionado y fiable."]},"constraints":["Una integración embebida y fluida entre Flex y Nayya Choose no era técnicamente viable.","El proyecto avanzaba con un cronograma muy ajustado y limitaciones técnicas importantes.","La experiencia debía proteger la confianza del usuario durante la toma de decisiones sobre beneficios."],"methodology":{"name":"Investigación y Descubrimiento","steps":[{"step":1,"label":"Comprender","description":"Se clarificó el recorrido de selección de beneficios y el papel de Nayya Choose como apoyo en la decisión."},{"step":2,"label":"Definir","description":"Se identificó la vía de integración viable entre Flex y la experiencia externa de Nayya."},{"step":3,"label":"Alinear","description":"Colaboración con los Líderes de Solución, el Product Owner, el Analista de Negocio y el equipo de desarrollo."},{"step":4,"label":"Validar","description":"Se recomendaron pruebas con usuarios para entender sus inquietudes antes de finalizar la transición."},{"step":5,"label":"Medir","description":"Se utilizó el comportamiento de inscripción y las proyecciones de ingresos para evaluar el impacto."}]},"design_strategy":["Definir una vía de integración realista en lugar de forzar una experiencia embebida que la plataforma no podía soportar.","Usar comunicación y señales visuales para explicar hacia dónde iban los usuarios, por qué importaba la transición y cómo Nayya Choose respaldaba sus decisiones de beneficios.","Proteger la continuidad entre Flex y Nayya Choose haciendo que la transición se sintiera intencionada, fiable y alineada con el recorrido de inscripción en su conjunto."],"reflections":[{"title":"Diseñar bajo restricciones.","body":"Diseñar bajo restricciones técnicas no significa comprometer la experiencia. Significa encontrar el camino más eficaz dentro de los límites que se te dan."},{"title":"Probar pronto, corregir pronto.","body":"Las pruebas con usuarios, incluso a pequeña escala, sacan a la luz las decisiones más importantes antes de que resulten costosas de corregir."},{"title":"La confianza es un problema de diseño.","body":"Cuando los usuarios cruzan los límites entre plataformas, la claridad y el contexto son lo que los mantiene avanzando."},{"title":"Las restricciones obligan a enfocarse.","body":"La imposibilidad de integrar Nayya de forma nativa llevó al equipo a invertir en el diseño de la transición, un área que suele pasarse por alto cuando la integración fluida parece la solución obvia."}],"nda_notice":null,"password":null,"external_link":null,"content_blocks":[{"id":"overview","type":"overview","title":"Resumen del Proyecto","body":""},{"id":"team-context","type":"custom","title":"Equipo","body":"Trabajé estrechamente con el Líder de UX y el Diseñador de Contenido para garantizar la coherencia tanto de la experiencia como de los mensajes bajo un cronograma ajustado. También colaboré con el Product Owner, el Analista de Negocio y los Líderes de Solución para alinear la experiencia propuesta con los objetivos de negocio y las realidades técnicas."},{"id":"situation","type":"custom","title":"Situación","body":"Los empleados necesitaban más apoyo a la hora de seleccionar beneficios, y Nayya Choose ofrecía un potente motor de recomendaciones para guiarlos hacia una cobertura más relevante.\n\nEl proyecto avanzaba con un cronograma muy ajustado y presentaba limitaciones técnicas importantes. Una integración embebida y fluida entre Flex y Nayya Choose no era viable."},{"id":"task","type":"custom","title":"Tarea","body":"Fui responsable de ayudar a definir la mejor vía de integración entre ambas plataformas, protegiendo al máximo la experiencia del usuario.\n\nEsto implicaba equilibrar el valor de negocio, las limitaciones técnicas y la confianza del usuario durante un proceso de toma de decisiones sensible."},{"id":"actions","type":"custom","title":"Acciones","body":"Dado que una integración fluida no era posible, identificamos que los usuarios tendrían que salir de Flex y acceder a Nayya Choose en una experiencia independiente.\n\nPara reducir la fricción, ayudé a recomendar pruebas con usuarios para entender mejor sus inquietudes antes de finalizar la experiencia.\n\nLa investigación mostró que los usuarios necesitaban una comunicación más clara sobre hacia dónde se dirigían, por qué importaba la transición, y señales visuales que hicieran que el cambio se sintiera intencionado y fiable."},{"id":"impact","type":"results","title":"Impacto","body":"La integración demostró un valor claro para los usuarios que interactuaron con Nayya Choose. Los participantes que completaron la encuesta se inscribieron en el doble de beneficios que quienes la omitieron, y el trabajo contribuyó a un crecimiento medible en los ingresos médicos, adicionales y de PEO.","payload":{"rows":[{"metric":"Objetivo de crecimiento anual - Médico","value":"2%"},{"metric":"Objetivo de crecimiento anual - Adicional","value":"8%"},{"metric":"Crecimiento médico FY26","value":"$1M"},{"metric":"Crecimiento adicional FY26","value":"$2M"},{"metric":"Impacto anual - Flex","value":"$6M"},{"metric":"Impacto anual - Todo PEO","value":"$10M"}],"insights":["Promedio base de planes por participante (2023-2025): 4.46","2026","• Participantes que \"se saltaron\" Nayya: 2.57","• Participantes que solo \"iniciaron\" Nayya: 4.43","• Participantes que recibieron recomendaciones de Nayya: 5.44"],"opportunities":["Menos del 7% de los empleados elegibles completó una encuesta de Nayya, lo que deja un amplio margen de crecimiento.","Aumentar la finalización al 10% podría añadir más de 10,000 planes y generar entre $2M y $7M en ingresos incrementales de beneficios PEO.","Otras oportunidades de investigación incluyen un análisis más profundo del comportamiento en la encuesta de Nayya y los cambios de inscripción interanuales.","Las posibles áreas de expansión del producto incluyen recomendaciones de 401(k), FinFit y PayActiv."]}}]}$case_es0$::jsonb
from public.case_studies
where slug = 
on conflict (case_study_id, locale) do update
set payload = excluded.payload;

insert into public.case_study_locales (case_study_id, locale, payload)
select id, , $case_es0${"slug":"flock-accessibility-system","status":"published","featured":false,"order":2,"title":"Auditoría de accesibilidad y unificación del sistema de diseño de Flock","company":"Flock","client_context":"Paychex a través de ITX Corp","role":"Diseñador de Producto","year":2025,"duration":"6 meses de auditoría + 1 año de construcción","industry":"Accesibilidad / Sistemas de Diseño","tagline":"Lideró una auditoría de accesibilidad y ayudó a unificar el sistema de diseño. Esto redujo la deuda de patrones, hizo el producto más coherente y mejoró la colaboración entre los equipos de diseño y desarrollo.","tags":["Accessibility","Design Systems","UX Research","Product Design","Axe","Design system","Voice Over"],"filters":["Accessibility","Design Systems","Product Design"],"tools":["Figma","Jira","Miro"],"images":{"cover":"/images/projects/flock-accessibility-system/thumbnails/flock.png","hero":"/images/projects/flock-accessibility-system/hero/flock-hero.png","gallery":[]},"client_logos":[],"metrics":[{"value":"6 months","label":"Auditoría y priorización","context":"revisión inicial de accesibilidad y del sistema"},{"value":"1 system","label":"Base compartida","context":"patrones, tipografía, iconos y diálogos alineados"}],"team":["1 diseñador","Líder de UX","Gerente de UX","Product Owner","Analista de Negocio","3 desarrolladores","Líder de Desarrollo"],"my_role":["Líder de Auditoría de Accesibilidad","Estrategia de Componentes","Sistemas de Diseño","Colaboración con Ingeniería"],"problem":{"admin_pain_points":["El producto tenía riesgos de accesibilidad en sus flujos principales y no contaba con una librería compartida madura para abordar los problemas de forma sistemática.","Los equipos trabajaban con patrones duplicados, nomenclatura inconsistente y un comportamiento de componentes fragmentado entre páginas.","Una documentación débil y la ambigüedad en la entrega generaban fricción en la implementación y dificultaban escalar las decisiones del sistema."],"user_pain_points":["Los componentes inconsistentes hacían que la experiencia fuera menos predecible de una página a otra.","Las carencias de accesibilidad reducían la claridad y usabilidad para las personas que dependían de una jerarquía más clara, un buen tratamiento del foco y estados de interacción coherentes.","Los diálogos, iconos, la tipografía y el comportamiento responsivo carecían de reglas compartidas suficientes para sentirse coherentes en todo el producto."]},"constraints":["Las mejoras de accesibilidad debían realizarse con el producto ya en producción y fragmentado en múltiples páginas y patrones.","No existía un sistema de diseño totalmente maduro, por lo que el trabajo de auditoría y la definición del sistema tuvieron que avanzar en paralelo.","El sistema debía sostener restricciones reales de ingeniería, control de calidad y preparación para la implementación, en lugar de quedarse en un simple esfuerzo de limpieza en Figma."],"methodology":{"name":"De la Auditoría a la Sistematización","steps":[{"step":1,"label":"Auditar","description":"Se revisaron problemas de accesibilidad y componentes que no coincidían con el sistema."},{"step":2,"label":"Estructurar","description":"Se agruparon los problemas por importancia para determinar qué corregir primero."},{"step":3,"label":"Sistematizar","description":"Se crearon patrones, estados y reglas claras sobre cómo debían funcionar los componentes."},{"step":4,"label":"Alinear","description":"Se trabajó con los desarrolladores para asegurar que los diseños pudieran construirse correctamente en React."},{"step":5,"label":"Validar","description":"Se revisaron diseños y builds, usando el feedback para mejorar la coherencia."}]},"design_strategy":["Clarificar las bases, componentes, patrones y módulos para que los equipos supieran cuándo usar cada patrón y cómo debía comportarse.","Se separaron las correcciones de accesibilidad de las decisiones del sistema de diseño documentando patrones, variantes, estados y reglas de uso.","Se trabajó estrechamente con los desarrolladores para adaptar las decisiones de componentes a las realidades de implementación, las necesidades de control de calidad y la claridad en la entrega.","Se utilizaron revisiones de diseño, comprobaciones de accesibilidad y feedback de implementación para reforzar la adopción y la coherencia."],"reflections":[{"title":"La usabilidad consiste en revelar lo que importa.","body":"La usabilidad no consiste en eliminar, sino en revelar lo que importa. Este proyecto demuestra que la accesibilidad, el rendimiento y la UX se refuerzan mutuamente cuando se tratan como una sola disciplina."}],"nda_notice":null,"password":null,"external_link":null,"content_blocks":[{"id":"overview","type":"overview","title":"Resumen","body":""},{"id":"team-context","type":"custom","title":"Equipo","body":"Lideré el planteamiento de la auditoría, definí qué patrones necesitaban consolidarse y colaboré con ingeniería sobre cómo debían comportarse los componentes en producción. Trabajé junto a otro diseñador, en colaboración con un Líder de UX, un Gerente de UX, un Product Owner, un Analista de Negocio, tres desarrolladores y un Líder de Desarrollo."},{"id":"situation","type":"custom","title":"Situación","body":"La falta de un sistema de diseño hizo que los iconos, la tipografía, los diálogos, los patrones de interfaz repetidos, el comportamiento inconsistente de los componentes y los patrones de UI reutilizables se fueran desviando con el tiempo.\n\nEso generaba fricción en la implementación, afectaba la preparación en accesibilidad, hacía las entregas menos fiables y aumentaba el coste de mantener la coherencia en la experiencia."},{"id":"task","type":"custom","title":"Tarea","body":"Mi papel era convertir los hallazgos de accesibilidad y las inconsistencias de la interfaz en una dirección de sistema clara, definiendo patrones reutilizables que diseño e ingeniería pudieran adoptar.\n\nEl producto había sido adquirido recientemente, así que el objetivo era mantener su identidad visual mientras se mejoraba la coherencia y la usabilidad mediante un sistema más escalable basado en React.\n\nEl éxito significaba reducir los patrones duplicados, mejorar el producto, clarificar las expectativas de entrega y crear una guía de accesibilidad más sólida para el trabajo futuro."},{"id":"actions","type":"custom","title":"Acciones","payload":{"items":["Construí un marco de auditoría que agrupaba los problemas por gravedad, impacto en el sistema y complejidad de implementación, separando los hallazgos de accesibilidad, las inconsistencias del sistema y las restricciones de ingeniería para facilitar la toma de decisiones.","Revisé las bases y los patrones compartidos entre iconos, tipografía, diálogos y componentes para identificar dónde había que estandarizar estados, variantes, nomenclatura y comportamiento responsivo. A partir de ahí, definí patrones reutilizables y una guía más clara en Figma para reducir la ambigüedad y mejorar la coherencia en la entrega.","También colaboré estrechamente con los desarrolladores durante la revisión y el control de calidad para adaptar los patrones a restricciones técnicas reales y confirmar que las decisiones de sistema propuestas funcionaban en producción."]}},{"id":"impact","type":"results","title":"Resultados de Producto/Sistema","body":"El proyecto creó una base de sistema más clara para la accesibilidad, la reutilización de componentes y la coherencia en la implementación. Como no se conservaron métricas de negocio confirmadas, los resultados se enmarcan a través de señales de producto, sistema y entrega.","payload":{"rows":[{"metric":"Riesgo de accesibilidad","value":"Reducido"},{"metric":"Deuda de patrones","value":"Reducida"},{"metric":"Claridad en la entrega","value":"Más sólida"}],"insights":["La auditoría hizo visible la gravedad y la priorización, lo que ayudó al equipo a abordar problemas estructurales de accesibilidad en lugar de correcciones aisladas de interfaz.","Una guía compartida para iconos, tipografía, diálogos y patrones reutilizables redujo la inconsistencia y dio al sistema una fuente de verdad más clara.","Definir estados, variantes y reglas de uso redujo la ambigüedad entre diseño e ingeniería y mejoró la calidad de las conversaciones de implementación."],"projected":["Una vía de adopción más clara para componentes, patrones y módulos reutilizables.","Una entrega y control de calidad más fiables gracias a que las notas de accesibilidad y la guía de uso están documentadas.","Menor riesgo en futuras revisiones de accesibilidad al abordar los problemas de forma sistémica en lugar de página por página.","La coherencia de patrones ayuda a los usuarios a entender las interacciones en las páginas."],"successMetrics":["Reducción de patrones de componentes duplicados o contradictorios.","Mejora de los estados, variantes y comportamiento responsivo de los componentes en los módulos reutilizados.","Menos preguntas de implementación durante la entrega y el control de calidad.","Problemas de accesibilidad identificados y resueltos por gravedad antes del lanzamiento."]}}]}$case_es0$::jsonb
from public.case_studies
where slug = 
on conflict (case_study_id, locale) do update
set payload = excluded.payload;

insert into public.case_study_locales (case_study_id, locale, payload)
select id, , $case_es0${"slug":"i9-everify-integration","status":"published","featured":false,"order":3,"title":"Integración de I-9 y E-Verify","company":"Paychex Flex","client_context":"Paychex a través de ITX Corp","role":"Diseñador de Producto Sr.","year":2024,"duration":"Alrededor de 3 años","industry":"Cumplimiento de RRHH / SaaS de Onboarding","tagline":"Rediseñé la integración de I-9 y E-Verify para Flex, aumentando la finalización posterior al lanzamiento del 69% al 81% y reduciendo el tiempo de finalización en un 26%.","tags":["UX Research","Product Design","Workflow Design","Compliance"],"filters":["UX Research","Product Design","Compliance"],"tools":["Figma","Jira","Miro","Webex","Outlook","Copilot"],"images":{"cover":"/images/projects/i9-everify-integration/thumbnails/i9-thumbnail.png","hero":"/images/projects/i9-everify-integration/hero/i9-banner.png","gallery":[]},"client_logos":[{"name":"Paychex","logo":"/images/c54fy.png"}],"metrics":[{"value":"76%","label":"de los clientes de Flex carecía de un flujo de I-9 conforme a la normativa"},{"value":"26","label":"Rondas de exploración y pruebas"},{"value":"2,548","label":"Respuestas de encuesta tras el primer lanzamiento"}],"team":["Product Owner","Gerente de Programa","Analista de Negocio","Investigador","Equipo de Desarrollo (12)","Gerente de UX","Líder de UX","Diseñador UX/UI","Arquitecto de Servicio","Scrum Master"],"my_role":["Investigación de Usuarios","Diseño UX/UI","Pensamiento de Producto","Narrativa"],"problem":{"admin_pain_points":["Los clientes solían depender de procesos manuales o soluciones personalizadas fuera de la plataforma para gestionar los requisitos de I-9 y E-Verify.","Los administradores necesitaban un seguimiento de estado más claro, acceso a documentos, visibilidad sobre la transferencia al proveedor y facturación por transacción vinculada al onboarding.","La experiencia debía sostener múltiples roles de usuario, escalabilidad futura y flujos de trabajo orientados al cumplimiento normativo."],"user_pain_points":["Los nuevos empleados debían completar la Sección 1 del Formulario I-9 como parte del onboarding sin sentirse desconectados de la experiencia de Flex.","Los usuarios necesitaban señales más claras antes de salir de Flex hacia la experiencia externa de HIREtech.","Empleados y administradores necesitaban una titularidad más clara, estados de progreso, feedback de finalización y acciones de seguimiento."]},"constraints":["El flujo de trabajo dependía de HIREtech, una experiencia de proveedor externo fuera de Flex.","El diseño debía contemplar los recorridos de empleados y administradores, las restricciones de cumplimiento normativo, las redirecciones al proveedor, los requisitos de facturación y el seguimiento de estado.","El producto debía escalar para trabajadores compartidos, clientes con el mismo FEIN, soporte de marca blanca y migración de documentos I-9 existentes."],"methodology":{"name":"Design Thinking","steps":[{"step":1,"label":"Investigar","description":"Se realizaron exploraciones de diseño y pruebas a lo largo de los recorridos de usuario."},{"step":2,"label":"Mapear","description":"Se mapeó dónde debía comenzar el flujo en Flex y en qué punto los usuarios transicionarían hacia HIREtech."},{"step":3,"label":"Alinear","description":"Se alineó I-9 con patrones de tareas de onboarding conocidos, como el W-4 y el depósito directo."},{"step":4,"label":"Clarificar","description":"Se definieron los momentos de transferencia, la visibilidad del estado, la titularidad de la tarea y el feedback de finalización."},{"step":5,"label":"Escalar","description":"Se consideraron necesidades futuras, incluyendo trabajadores compartidos, clientes con el mismo FEIN, soporte de marca blanca y migración de documentos."}]},"design_strategy":["Usar una comunicación de transferencia más clara, estados de progreso y feedback de finalización para reducir la confusión en torno a la experiencia externa de HIREtech."],"reflections":[{"title":"Lo que funcionó.","body":"Anclar un flujo de trabajo cargado de cumplimiento normativo a patrones de onboarding conocidos hizo que I-9 se sintiera parte nativa del producto en lugar de una tarea añadida. Una sola prueba de usabilidad con 7 usuarios bastó para cambiar una decisión de producto y proteger una mejor experiencia: los datos superan a la opinión. Combinar pruebas iterativas con una estrategia de transferencia clara creó una base más sólida tanto para la usabilidad como para el crecimiento del negocio."},{"title":"Qué haría diferente.","body":"Establecer antes la alineación con el proveedor externo: esperar la validación de cumplimiento de HIREtech generó retrabajo y ralentizó las iteraciones de diseño. Avanzar más rápido en las decisiones de contenido de cumplimiento normativo, estableciendo puntos de aprobación más claros desde el principio en lugar de iterar en círculos, habría ahorrado tiempo."},{"title":"Qué desbloqueó esto.","body":"El proyecto puso de manifiesto un patrón inexistente en Flex para comunicar a los usuarios las transiciones a terceros. Resolverlo aquí creó un patrón de transparencia reutilizable que abordó un problema sistémico presente en múltiples integraciones de la plataforma."}],"nda_notice":null,"password":null,"external_link":null,"content_blocks":[{"id":"situation","type":"custom","title":"Situación","body":"Los clientes de Flex completaban los requisitos de I-9 y E-Verify fuera de la plataforma, dependiendo de coordinación manual, herramientas externas y seguimiento por parte de los administradores para cerrar las brechas de cumplimiento.\n\nAlrededor del 76% de los usuarios se veían afectados, lo que generaba tasas de finalización inconsistentes, mayor riesgo de error y una carga de soporte más alta en los flujos de contratación.\n\nSin un flujo de trabajo nativo, no había forma fiable de seguir el estado, confirmar la titularidad o garantizar que el cumplimiento se completara a tiempo."},{"id":"task","type":"custom","title":"Tarea","body":"","payload":{"items":["Fui responsable de todo el proceso de UX de principio a fin como único diseñador, desde la investigación hasta la entrega final.","Diseñé tanto el recorrido del empleado (Sección 1) como el del administrador (Sección 2 y seguimiento de estado).","Integré I-9 y E-Verify en Flex sin fragmentar la experiencia de onboarding existente.","Facilité una sesión de trabajo con analistas de negocio, ingenieros y líderes de producto para identificar preguntas abiertas, restricciones de integración y brechas con el proveedor externo HIREtech."]}},{"id":"alternatives","type":"custom","title":"Alternativas exploradas","body":"","payload":{"subtitle":"","items":[]}},{"id":"research","type":"custom","title":"La Solución","body":"","payload":{"items":[],"delivery_items":["Se entregaron especificaciones de diseño detalladas para desarrollo, incluyendo comportamientos, ejemplos de contenido, definiciones de componentes y documentación de casos límite.","Se diseñaron comunicaciones por correo electrónico para anunciar la nueva integración y hacer seguimiento a los usuarios que no completaron el proceso de I-9.","Se crearon directrices de transferencia que documentaban cómo se comunicaba a los usuarios la integración de Flex con HIREtech, cubriendo los mensajes de redirección, los estados de progreso y el feedback de finalización."]}},{"id":"actions","type":"custom","title":"Acciones","body":"","payload":{"items":[]}},{"id":"impact","type":"results","title":"Resultado","body":"","payload":{"rows":[{"metric":"Tasa de finalización de tareas del empleado","value":"12%"},{"metric":"Tiempo medio en la tarea","value":"−26%"},{"metric":"Titubeo ante la redirección","value":"−13%"},{"metric":"Errores de interpretación del estado","value":"−9%"},{"metric":"Puntuación de confianza del usuario","value":"0.8"}],"insights":["Tasa de finalización de tareas: del 69% (concepto inicial) al 81% (concepto refinado).","Tiempo medio en la tarea: de 4m 12s a 3m 06s.","El titubeo ante la redirección se redujo del 46% al 33%.","Los errores de interpretación del estado bajaron del 31% al 22%.","La puntuación de confianza del usuario mejoró de 3.2/5 a 4.0/5.","La dependencia de procesos manuales se estableció en un valor base de 60–70%; el objetivo se fijó por debajo del 25% para el seguimiento posterior al lanzamiento.","2,548 respuestas de encuesta tras el primer lanzamiento confirmaron que la dirección integrada estaba funcionando."],"opportunities":["Los empleados que abandonaban el flujo a mitad de camino no tenían forma de guardar el progreso, lo que generaba riesgo de abandono y envíos de I-9 incompletos.","Añadir un estado de guardado en el formulario podría mejorar directamente las tasas de finalización y reducir el seguimiento administrativo de los casos incompletos.","Se identificó una desalineación de contenido entre HIREtech y Flex durante las pruebas; se entregaron directrices de comunicación actualizadas, pendientes de confirmación por parte de HIREtech.","El patrón de transparencia desarrollado para esta integración abre la puerta a aplicar la misma estrategia de transferencia en otros flujos de trabajo con terceros dentro de Flex."]}}]}$case_es0$::jsonb
from public.case_studies
where slug = 
on conflict (case_study_id, locale) do update
set payload = excluded.payload;

insert into public.case_study_locales (case_study_id, locale, payload)
select id, , $case_es0${"slug":"protecta","status":"published","featured":false,"order":6,"title":"Marca, sitio web y lanzamiento de campaña","company":"Protecta Advisory","client_context":"Sitio web bilingüe de asesoría de seguros para familias multiculturales en Estados Unidos","role":"Ingeniero de Diseño","year":2026,"duration":"72% más rápido en la creación web","industry":"Seguros / Asesoría","tagline":"Diseñé una campaña de concienciación sobre seguros y un recorrido de conversión que transforma el alcance en redes sociales en consultas directas por WhatsApp y oportunidades de consulta cualificadas.","tags":["AI Product","Product Design","Brand Strategy","Content Design","Accessibility","Localization"],"filters":["AI Product","Product Design","Accessibility"],"tools":["NotebookLM","Claude","Figma AI","Codex","Claude Code","Storybook","Grammarly","Vercel"],"images":{"cover":"/images/projects/protecta/thumbnails/protectabanner.png","hero":"/images/projects/protecta/hero-banner.png","gallery":["/images/projects/protecta/screenshots/protecta-home-desktop.png","/images/projects/protecta/screenshots/protecta-home-mobile.png"]},"client_logos":[],"metrics":[{"value":"72%","label":"Entrega web más rápida","context":"Flujo de trabajo asistido por IA para la marca, el contenido bilingüe, el diseño y desarrollo web, QA y lanzamiento."},{"value":"98%","label":"Alcance de nueva audiencia","context":"Visualizaciones de personas que no seguían la página durante los primeros 28 días de la campaña."},{"value":"WCAG 2.1 AA","label":"Objetivo de accesibilidad","context":"Las comprobaciones de accesibilidad a nivel de componente se gestionaron en Storybook durante la construcción."}],"team":["Diseñador en solitario","Asesores del cliente","Fundadores del cliente para las aprobaciones finales"],"my_role":["Diseñador UX/UI","Estratega de Marca","Estratega y Redactor de Contenido","Product Owner","Desarrollador","Ingeniero de QA","Líder de Localización Bilingüe"],"problem":{"admin_pain_points":["Protecta tenía un modelo de servicio claro y un programa de referidos sólido, pero carecía de un sistema de marca, un sitio web en producción y contenido estructurado para respaldar el crecimiento.","El programa de referidos, el modelo de asesoría y la vía de contacto por WhatsApp debían explicarse con claridad y resultar confiables para las familias que toman decisiones sensibles sobre seguros."],"user_pain_points":["Los prospectos necesitaban una alternativa más cálida y humana a la experiencia de centro de llamadas que suelen asociar con los sitios web de seguros.","Las familias hispanohablantes necesitaban contenido que se sintiera nativo y culturalmente natural, no como una traducción directa de un sitio pensado primero en inglés.","Los visitantes necesitaban entender con claridad el programa de referidos y contar con una vía sencilla para contactar con los asesores sin fricción."]},"constraints":["Un cronograma comprimido que abarcaba estrategia, marca, contenido, diseño, construcción, control de calidad y despliegue.","No existía un sistema de marca previo, ni un sitio web anterior, ni contenido listo para publicar.","No hubo investigación directa con usuarios dentro del cronograma; las entrevistas con asesores y el conocimiento del cliente actuaron como señal indirecta de usuario."],"methodology":{"name":"Flujo de Trabajo de Entrega Potenciado por IA","steps":[{"step":1,"label":"Capturar","description":"Se realizó una llamada estructurada con el cliente y un cuestionario para capturar las necesidades de la audiencia, el flujo de ventas, las objeciones, la mecánica de referidos y el tono, como fuente de verdad."},{"step":2,"label":"Investigar","description":"Se utilizó NotebookLM para sintetizar rápidamente patrones de la industria, el posicionamiento competitivo, las normas de seguros bilingües y las oportunidades estructurales."},{"step":3,"label":"Marca","description":"Se usó Claude Design para el primer borrador visual, y luego se seleccionaron e iteraron las direcciones más sólidas a partir de la investigación, la estructura y el criterio de diseño."},{"step":4,"label":"Redactar","description":"Se usó Claude para los primeros borradores de texto, y después se reescribió la jerarquía de mensajes y se adaptó el contenido en español de forma nativa."},{"step":5,"label":"Diseñar","description":"Se usó Figma AI para convertir la dirección seleccionada en una biblioteca de componentes reutilizables y después se iteraron la página de inicio y las páginas internas con esos componentes, variantes y estados bilingües."},{"step":6,"label":"Construir","description":"Se usó la biblioteca de componentes de Figma como referencia de implementación. Se generó el andamiaje con Codex, se terminaron los detalles con Claude Code y se ajustó el resultado a mano hasta lograr una calidad de producción."},{"step":7,"label":"Validar","description":"Se mantuvieron alineadas la biblioteca de Figma y los componentes en código, se documentaron los estados de implementación en Storybook, se verificó la accesibilidad conforme a WCAG 2.1 AA y se desplegó el producto funcional en Vercel."}]},"design_strategy":["El proyecto se estructuró en torno a una decisión central: usar la IA para comprimir la investigación, el andamiaje de textos y la aceleración de la construcción, reservando el criterio de diseño para el tono de marca, la jerarquía, la accesibilidad y los momentos de generación de confianza.","Dado que el diferenciador de Protecta es una asesoría humana y continua durante todo el año, el sitio debía sentirse cálido y creíble, en lugar de pulido de una forma genérica propia de una insurtech.","La estrategia bilingüe no partía de la traducción. El contenido en inglés y en español se construyó como sistemas de voz paralelos, para que cada recorrido de audiencia se sintiera intencionado.","Traté el sitio en producción, y no un mazo estático de diseño, como el artefacto de revisión. Eso cambió la calidad del feedback del cliente, porque este evaluó una experiencia funcional en dispositivos reales."],"reflections":[{"title":"La IA es mejor para comprimir que para crear.","body":"La mayor ganancia vino de comprimir la síntesis de la investigación, los primeros borradores de texto y el andamiaje de código. El criterio de marca, la jerarquía y las señales de confianza seguían necesitando que un diseñador tomara las decisiones."},{"title":"La localización es una decisión de diseño.","body":"La experiencia en español necesitaba adaptación cultural, no traducción literal. Eso cambió el tono, la redacción y la forma en que la tranquilidad se manifestaba en la interfaz."},{"title":"Un producto en producción cambia la calidad de la revisión.","body":"Mostrar al cliente un sitio funcional, en lugar de pantallas estáticas, hizo que el feedback fuera más rápido y fundamentado, porque pudo evaluar la experiencia real en vez de imaginarla."}],"nda_notice":null,"password":null,"external_link":null,"content_blocks":[{"id":"team-context","type":"custom","title":"Equipo","body":"Llevé el proyecto como una entrega en solitario abarcando siete roles: diseño UX/UI, estrategia de marca, estrategia y redacción de contenido, titularidad de producto, desarrollo, control de calidad y localización bilingüe. El cliente intervino en los puntos de decisión finales en lugar de participar en cada revisión intermedia."},{"id":"situation","type":"custom","title":"Situación","body":"Protecta es una asesoría independiente de seguros de salud y vida que atiende a familias multiculturales en Estados Unidos, en inglés y en español. Su valor diferencial es un acompañamiento humano y continuo durante todo el año, lo opuesto a la sensación de centro de llamadas habitual en esta categoría.\n\nYa contaban con un fuerte impulso de boca a boca y un modelo de referidos que paga incentivos en efectivo, pero no tenían sistema de marca, ni sitio web, ni una arquitectura de contenido que explicara ese valor con claridad en internet."},{"id":"task","type":"custom","title":"Tarea","body":"Entregar un sitio web bilingüe completo con marca propia, incluyendo página de inicio, páginas internas, estrategia de contenido, sistema de marca, estructura de componentes, control de calidad de accesibilidad y despliegue en producción.\n\nEl sitio debía explicar el programa de referidos, transmitir confianza rápidamente y ofrecer a los prospectos una vía de bajo esfuerzo para contactar con los asesores a través de WhatsApp."},{"id":"research","type":"custom","title":"Investigación","body":"Fundamenté el trabajo en el 2026 Hispanic Insurance Growth Blueprint, el cuestionario del cliente y las entrevistas con los asesores, con foco en adquisición para ACA, vida y canales digitales. Los asesores revelaron objeciones recurrentes, inquietudes de confianza y preguntas reales de las familias.\n\nLa IA aceleró la síntesis de investigación, las definiciones de trabajo y el análisis de patrones bilingües y brechas de posicionamiento. Convertí esos hallazgos en decisiones de audiencia, mensaje, canales y medición; validé los resultados frente al material fuente y tomé las decisiones finales de marca y producto."},{"id":"actions","type":"custom","title":"Alineación con IA","body":"Estructuré el trabajo como un flujo de producción potenciado por IA, con criterio humano en cada entrega. Claude y NotebookLM aceleraron la ideación, la síntesis de la investigación y los primeros borradores de texto.\n\nClaude Design creó la dirección visual inicial; después seleccioné y refiné las ideas más sólidas en Figma. Con Figma AI, construí la biblioteca de componentes reutilizables y sus variantes antes de usarla como referencia para la interfaz en código. Codex y Claude Code aceleraron la implementación, mientras Storybook documentó los componentes implementados y ayudó al control de calidad de accesibilidad."},{"id":"impact","type":"results","title":"Resultado","body":"El resultado combina un sitio web bilingüe listo para el lanzamiento con una campaña educativa diseñada para hacer que la cobertura médica sea fácil de entender y de aplicar para las familias. En sus primeros 28 días, la campaña generó descubrimiento orgánico, interacción y tráfico de una audiencia compuesta casi por completo por personas nuevas para la página.","payload":{"rows":[{"metric":"Visualizaciones de contenido","value":"3.3K"},{"metric":"Espectadores únicos","value":"1,436"},{"metric":"Interacciones de contenido","value":"129"},{"metric":"Clics en enlaces","value":"34"},{"metric":"Visitas a Facebook","value":"55"},{"metric":"Nuevos seguidores netos","value":"+12"}],"insights":["Periodo analizado: del 10 de julio al 6 de agosto de 2026 (28 días).","El 98% de las visualizaciones provino de personas que no seguían la página, lo que demuestra que el contenido educativo llegó mucho más allá de la audiencia existente.","115 de las 129 interacciones de contenido (89%) provinieron de personas que no seguían la página, lo que confirma que la campaña generó interacción de nuevas audiencias y no solo de seguidores actuales.","Se superaron los objetivos iniciales de alcance: Facebook alcanzó 1.5K frente a una meta de 208 (707%), e Instagram alcanzó 567 frente a una meta de 169 (336%).","El gráfico de resultados muestra las mayores ganancias después del despliegue programado de agosto, una primera señal de que la cadencia de publicación bilingüe y organizada está funcionando."],"projected":["Conectar los clics en enlaces y las consultas por WhatsApp con una fuente de leads para que el siguiente ciclo de reportes mida conversaciones cualificadas y conversión, no solo reconocimiento.","Mantener la cadencia de contenido bilingüe en torno a momentos estacionales de salud familiar y comparar formatos, mensajes y horarios de publicación.","Sustituir las imágenes de stock provisionales por una sesión real de fotos y vídeo con los propios asesores."]}}]}$case_es0$::jsonb
from public.case_studies
where slug = 
on conflict (case_study_id, locale) do update
set payload = excluded.payload;

insert into public.case_study_locales (case_study_id, locale, payload)
select id, , $case_es0${"slug":"reversetech","status":"published","featured":false,"order":7,"title":"Optimización del embudo de Reverse Health y pruebas A/B","company":"Reverse Health","client_context":"Embudo de adquisición mediante búsqueda de pago","role":"Diseñador de Producto Sr.","year":2026,"duration":"Estrategia y análisis de embudo","industry":"Salud y Fitness / Embudo de Crecimiento","tagline":"Un caso de estudio centrado en crecimiento sobre cómo interpretar datos del embudo, identificar problemas de UX y conversión, y convertir esos hallazgos en soluciones de diseño comprobables.","tags":["Growth","UX Research","Product Design","Paid Acquisition","Funnel Optimization"],"filters":["UX Research","Product Design"],"tools":["Figma","Google Ads","Analytics","Miro","Notion"],"images":{"cover":"/images/projects/reversetech/thumbnails/project-list-card-reversetech.svg","hero":"/images/projects/Reversetech/figma-screen.png","gallery":[]},"client_logos":[],"metrics":[],"team":["Equipo de Crecimiento","Partes interesadas de adquisición pagada","Diseñador de producto","Socios de analítica"],"my_role":["Interpretación de Datos del Embudo","Identificación de Problemas de UX y Conversión","Diseño de Experimentos de Muro de Pago","Planteamiento de Soluciones de Diseño Comprobables"],"problem":{"admin_pain_points":["El embudo convertía solo un 0.63% de extremo a extremo, lo que generaba presión para optimizar rápido sin evidencia clara de dónde ocurría realmente la fuga.","Como la experiencia contenía 44 pasos, el equipo podía inclinarse fácilmente por la explicación más visible, que el cuestionario simplemente era demasiado largo, sin antes comprobar si ese era realmente el problema dominante."],"user_pain_points":["La mayoría de los visitantes llegaban en frío desde Google Ads, así que cada paso tenía que justificar por qué debían continuar antes de haber generado suficiente confianza.","La parte central del embudo contenía más de 37 pasos de cuestionario, lo que hacía fácil asumir que el propio coste de interacción estaba expulsando a los usuarios.","Sin un diagnóstico más preciso, cualquier rediseño corría el riesgo de pulir la parte central mientras ignoraba partes más débiles del embudo, antes o después de ella."]},"constraints":[],"methodology":{"name":"Diagnóstico del Embudo","steps":[{"step":1,"label":"Mapear","description":"Se documentó el embudo completo desde el clic en el anuncio de Google hasta la compra, pasando por el cuestionario de 44 pasos, identificando dónde creía el equipo que la fricción era mayor."},{"step":2,"label":"Cuestionar","description":"Se cuestionó la suposición por defecto de que la larga parte central era el problema principal, replanteando el problema como un diagnóstico a nivel de embudo en lugar de una queja sobre el número de pasos."},{"step":3,"label":"Desglosar","description":"Se separó la experiencia en la promesa de adquisición, la experiencia de entrada, la progresión del cuestionario y la transición posterior al cuestionario, para poder evaluar cada parte por sus propios méritos."},{"step":4,"label":"Priorizar","description":"Se enfocó al equipo en identificar qué sección del embudo estaba realmente perdiendo intención de compra antes de comprometerse con una dirección de rediseño."},{"step":5,"label":"Definir los próximos pasos","description":"Se definió el planteamiento central del problema que debía resolver la siguiente fase de diseño, en lugar de asumir que la respuesta era acortar el cuestionario."}]},"design_strategy":["El paso de introducir el email se eligió para la propuesta de diseño por ser el segundo mayor punto de abandono dentro del embudo y uno de los momentos más críticos de pérdida de usuarios. El problema principal es un intercambio de valor débil: se pide a los usuarios su email y su atención antes de que vean con claridad qué van a recibir a cambio. Como resultado, el paso se percibe más como captación de leads que como parte de la experiencia de plan personalizado, y esta es la solución de diseño propuesta.","Hipótesis 3","Para reducir la fricción, las páginas anteriores al email deberían preparar mejor a los usuarios mostrando el progreso, reforzando por qué importa cada pregunta y anticipando el valor del plan final.","Añadir señales de confianza, progreso visible, vistas previas de la app e imágenes más relevantes también haría que la petición se sintiera más segura y más conectada con el producto."],"reflections":[{"title":"El problema evidente no siempre es el real.","body":"Un cuestionario largo es fácil de culpar porque es visible. Eso no lo convierte automáticamente en el punto de mayor impacto para intervenir."},{"title":"El tráfico frío cambia el estándar.","body":"Los visitantes que llegan desde Google Ads todavía no han generado mucha confianza, así que cada parte del embudo tiene que esforzarse más de lo que lo haría con una audiencia cálida."},{"title":"El diagnóstico es trabajo de diseño.","body":"Antes de cambiar diseños o reducir pasos, el equipo necesitaba entender con más precisión dónde se estaba perdiendo realmente la intención de compra."}],"nda_notice":"Algunos detalles del embudo se han resumido para su uso en el portafolio, pero la estructura, el contexto de tráfico y el problema de conversión reflejan el proyecto real.","password":null,"external_link":null,"content_blocks":[{"id":"overview","type":"overview","title":"Resumen del Proyecto","body":""},{"id":"team-context","type":"custom","title":"Equipo","body":"Trabajé en conversaciones de crecimiento y de producto para ayudar a definir el problema real antes de invertir esfuerzo de diseño en el lugar equivocado. El trabajo requería alinear el pensamiento de adquisición, el comportamiento del embudo y el diagnóstico de experiencia de usuario."},{"id":"situation","type":"custom","title":"Situación","body":"Reverse Health tenía en marcha un embudo con un cuestionario de 44 pasos que vendía un programa de calistenia para mujeres. De extremo a extremo, el embudo convertía un 0.63%.\n\nEl tráfico era mayoritariamente búsqueda de pago en frío, y una visita típica comenzaba desde un anuncio de Google. Dentro del equipo, la explicación más intuitiva era que la larga parte central del cuestionario, con más de 37 pasos, tenía que ser donde los usuarios abandonaban."},{"id":"task","type":"custom","title":"Tarea","body":"El alcance del trabajo se centraba en el diagnóstico del embudo y las mejoras de diseño, el diseño de experimentos de muro de pago y la extracción de patrones de la competencia.\n\nMi papel era interpretar los datos del embudo, identificar problemas de UX y conversión, y traducir esos hallazgos en soluciones de diseño concretas y comprobables dentro de un entorno de producto orientado al rendimiento."},{"id":"task-1","type":"custom","title":"Tarea 1","body":"En lugar de tratar todos los pasos por igual, revisé los 44 y elegí 3 para examinar, equilibrando la fuga de usuarios, el volumen de usuarios y la influencia sobre los pasos posteriores. Después, para cada uno profundicé en dos preguntas: por qué se comporta como lo hace, y qué comportamiento de usuario, fricción o problema de claridad explica los datos.","payload":{"heading":"Diagnóstico del embudo y mejoras de diseño","table":[{"step":"31. edad","churnCount":"7","churnPercent":"0.13%","userCount":"5,403","remainingPercent":"18.03%","dotColor":"#5ca95c"},{"step":"4. Objetivo principal","churnCount":"224","churnPercent":"3.20%","userCount":"6,784","remainingPercent":"22.64%","dotColor":"#ffd45c"},{"step":"34. introducir email","churnCount":"1,156","churnPercent":"21.62%","userCount":"4,190","remainingPercent":"13,99%","dotColor":"#ff2d2d","tag":"Selección de diseño"}],"analyses":[{"title":"31. Paso de la edad - Buen rendimiento","body":"Un paso claro y de bajo esfuerzo. A esta altura, abandonar el flujo se sentiría como un desperdicio, así que los usuarios continúan. La carga cognitiva y emocional es mínima, no hay ninguna decisión financiera asociada, y la mayoría entiende que la edad importa en un plan de salud.","consideration":"La edad se pregunta dos veces, en la landing y de nuevo en el paso 31. Probarlo en un único paso podría reducir el esfuerzo y acortar el embudo.","image":"/images/projects/Reversetech/age.png"},{"title":"4. Objetivo principal - Rendimiento regular","body":"La opción de selección única lo mantiene ligero y evita sobrecargar de decisiones a los usuarios. La fricción es más sutil: este es el momento en que el usuario le dice al producto qué resultado quiere, por lo que nombrar un objetivo conlleva peso emocional. Una hipótesis, basada en la investigación, es que seleccionar un objetivo añade peso y eso puede sentirse como presión, especialmente cuando las opciones no encajan del todo con el usuario o este todavía no se ha decidido.","consideration":"Probar una versión con distintas opciones de contenido y añadir una opción de \"Ayúdame a elegir el objetivo adecuado\". Además, reducir el número de pasos antes de esta pregunta, para que los usuarios lleguen antes a su momento de definir el objetivo, mientras la intención todavía es alta.","image":"/images/projects/Reversetech/goal.png"},{"title":"34. Introducir email - Mal rendimiento","body":"Esta es la segunda mayor fuga dentro del embudo, y es el peor lugar posible para perder gente. En este punto, los usuarios todavía no pueden ver el valor del producto, así que pedir un email sin explicar el beneficio puede sentirse como un paso de captación de marketing en lugar de parte de la experiencia de plan personalizado.","consideration":"Algunos usuarios también intuyen que se acerca el muro de pago. Entregar un email justo antes de una probable petición de pago hace que el muro se sienta más cercano, por lo que una parte abandona de forma preventiva.","image":"/images/projects/Reversetech/email.png"}]}},{"id":"cta-variants","type":"custom","title":"Variante de CTA","body":"El contenido del paso de email no se siente lo bastante personalizado como para que los usuarios crean que se está construyendo un resultado a medida para ellos. La página de email debería reconectarlos con su objetivo, mostrar un adelanto de lo que van a recibir y usar textos orientados al resultado.","payload":{"variants":[{"label":"Variante 1","title":"Ver mi plan personalizado","body":"Hace la oferta más específica al nombrar directamente el plan de Calistenia. La hipótesis es que una etiqueta de producto más clara puede hacer que el paso de email se sienta más creíble y menos como una captación de leads genérica.","imageSrc":"/images/projects/Reversetech/cta-variant-1.svg"},{"label":"Variante 2","title":"Obtener mi plan de calistenia","body":"Presenta la petición de email de forma ligeramente más limpia. Pone a prueba si reducir el texto adicional alrededor del campo hace que el paso se sienta más rápido, sin dejar de dar a los usuarios suficiente confianza para continuar.","imageSrc":"/images/projects/Reversetech/cta-variant-2.svg"},{"label":"Variante 3","title":"Desbloquear mi plan personalizado","body":"Es la más minimalista. Se apoya en el titular personalizado de Calistenia para hacer la mayor parte de la persuasión.","imageSrc":"/images/projects/Reversetech/cta-variant-3.svg"}]}},{"id":"content-variants","type":"custom","title":"Variante de Contenido","body":"A esta altura, los usuarios ya han invertido tiempo en el cuestionario, pero todavía no han visto con claridad el valor del producto. Como el progreso no es visible, el embudo puede sentirse más largo de lo necesario, generando fatiga incluso cuando cada pantalla es sencilla. Esto hace que la petición de email se sienta abrupta en lugar de merecida.\n\nComo resultado, el paso se percibe más como captación de leads que como parte de la experiencia de plan personalizado, y esta es la solución de diseño propuesta. Para efectos de esta tarea, seleccioné la Variante 3 como solución de diseño final, aunque creo que un buen enfoque sería probar varias ideas mediante A/B testing.","payload":{"variants":[{"label":"Variante 3","title":"Variación: Categoría, Titular, Subtítulo y Texto de Ayuda","body":"Introduce un mensaje enérgico centrado en resultados y vincula el plan a un resultado físico concreto. Es más motivadora que las demás, pero depende de una fuerte relevancia.","imageSrc":"/images/projects/Reversetech/content-variant-3.svg"},{"label":"Variante 2","title":"Categoría, Titular, Subtítulo y Texto de Ayuda","body":"Mantiene el planteamiento de plan listo y lo combina con una garantía directa de que no habrá spam. Es la variante de contenido más segura porque aclara qué obtiene el usuario mientras reduce la ansiedad por la privacidad sin añadir demasiada explicación extra.","imageSrc":"/images/projects/Reversetech/content-variant-2.svg"},{"label":"Variante 1","title":"Categoría y Titular","body":"Personaliza el titular según el objetivo seleccionado por el usuario. Hace que el resultado se sienta relevante y a medida, manteniendo el paso de email conectado con lo que el usuario ya eligió. La contrapartida es que estrecha la promesa antes, por lo que el objetivo principal seleccionado necesita estar aquí para mantener las motivaciones del usuario.","imageSrc":"/images/projects/Reversetech/content-variant-1.svg"}]}},{"id":"impact","type":"results","title":"Impacto","body":"Transformé la evidencia del embudo en diseños priorizados y comprobables para la brecha de conversión del paywall. La variante ganadora lanzada aumentó la conversión de extremo a extremo del 0.63% al 0.77%: un incremento de 0.14 puntos porcentuales, o un 22% de mejora relativa, equivalente a 14 compras adicionales por cada 10,000 visitas cualificadas.","payload":{"rows":[],"insights":["La parte central del cuestionario parecía el problema porque era larga y muy visible.","El tráfico frío de búsqueda de pago elevó el coste de cada compromiso en el embudo, no solo el de los propios pasos del cuestionario.","El resultado más importante de esta fase fue replantear el trabajo de \"acortar el cuestionario\" a \"diagnosticar primero el cuello de botella real\"."],"opportunities":["Comparar el abandono y la calidad de la intención entre la entrada desde la landing, la parte central del cuestionario y la transición de compra posterior al cuestionario.","Comprobar si la promesa del anuncio y la expectativa de la landing están lo bastante alineadas para el tráfico de búsqueda en frío, antes de pedir a los usuarios que se comprometan con un flujo largo.","Identificar qué momentos del cuestionario generan impulso y cuáles simplemente añaden coste de interacción."]}},{"id":"sources","type":"custom","title":"Fuentes","body":"","payload":{"sources":[{"title":"Nielsen Norman Group — \"Progress Indicators Make a Slow System Less Insufferable\"","url":"https://www.nngroup.com/articles/progress-indicators/","description":"Respalda la idea de que el feedback de progreso reduce la incertidumbre y mantiene a los usuarios avanzando. Advertencia: este artículo de NN/g trata sobre el progreso de sistemas y tiempos de espera, no sobre contadores de varios pasos, por lo que funciona mejor combinado con la investigación sobre el efecto gradiente de meta citada más abajo, específicamente para el punto sobre el número de pasos."},{"title":"Baymard Institute — \"Checkout Flows Average 5 Steps and 11+ Form Fields\"","url":"https://baymard.com/blog/checkout-flow-average-form-fields","description":"Respalda unificar preguntas en lugar de limitarse a dividir pasos: el número de campos de formulario que el usuario debe gestionar importa más para la UX del checkout que el número de pasos, y la mayoría de los flujos pueden reducirse a entre 6 y 8 campos."},{"title":"The Manifest — \"6 Steps for Avoiding Online Form Abandonment\"","url":"https://themanifest.com/web-design/6-steps-avoiding-online-form-abandonment","description":"Se utiliza para el dato de que el 27% de los usuarios abandona un formulario por ser demasiado largo, y una vez que abandonan, rara vez regresan. Advertencia: se trata de una encuesta de 2018 con 502 personas, así que lo considero un dato desactualizado."},{"title":"Nunes & Drèze (2006), Journal of Consumer Research — \"The Endowed Progress Effect: How Artificial Advancement Increases Effort\"","url":"https://academic.oup.com/jcr/article-abstract/32/4/504/1787425","description":"El origen exacto del término \"efecto de progreso dotado\" (endowed progress effect): las personas a las que se les da un avance artificial hacia una meta muestran mayor persistencia para alcanzarla."},{"title":"Kivetz, Urminsky & Zheng (2006), Journal of Marketing Research — \"The Goal-Gradient Hypothesis Resurrected\"","url":"https://journals.sagepub.com/doi/abs/10.1509/jmkr.43.1.39","description":"Respalda la afirmación de que las personas aceleran su esfuerzo a medida que se acercan a una recompensa. Lo utilizo cuando hago referencia al efecto gradiente de meta (goal-gradient effect).","secondaryTitle":"Resumen de Columbia Business School","secondaryUrl":"https://business.columbia.edu/insights/chazen-global-insights/goal-gradient-hypothesis-resurrected-purchase-acceleration"},{"title":"IBM Carbon Design System — Progress indicator, usage guidelines","url":"https://carbondesignsystem.com/components/progress-indicator/usage/","description":"Una referencia autorizada de sistema de diseño sobre cómo mostrar a los usuarios dónde se encuentran: dividir la meta final en subtareas más pequeñas aumenta la sensación de completitud, y mantener informados a los usuarios de dónde están les da sensación de control."},{"title":"WebAIM Million 2025 report","url":"https://webaim.org/projects/million/2025","description":"Se utiliza para el ángulo de accesibilidad sobre el campo de email: las páginas de inicio tenían un promedio de 6.3 campos de formulario, y el 34.2% de esos campos no estaban correctamente etiquetados. Nota: la cifra del 48% que circula en fuentes secundarias es el porcentaje de páginas de inicio con al menos un campo sin etiquetar, que es una métrica distinta."},{"title":"HubSpot — \"10 Form Conversion Optimization Tips\"","url":"https://blog.hubspot.com/marketing/optimize-conversion-forms","description":"Del análisis de HubSpot de más de 40,000 landing pages: los botones etiquetados como \"Submit\" tenían tasas de conversión más bajas, y los formularios de 3 campos convertían mejor, con una caída a partir de ahí. Lo utilizo para los puntos de \"el texto orientado al resultado supera a 'continuar'\" y \"mantener la petición mínima\"."}]}}]}$case_es0$::jsonb
from public.case_studies
where slug = 
on conflict (case_study_id, locale) do update
set payload = excluded.payload;

insert into public.case_study_locales (case_study_id, locale, payload)
select id, , $case_es0${"slug":"calendar-keeper","status":"published","featured":false,"order":8,"title":"Administrador de calendario","company":"HRS","client_context":"HRS","role":"Diseñador Sr de Producto","year":2026,"duration":"Sprint de descubrimiento independiente asistido por IA","industry":"SaaS de gestión de consultas y atención sanitaria","tagline":"Descubrimiento de productos asistido por IA para la programación clínica, convirtiendo las dependencias de recursos, las interrupciones y las limitaciones de cumplimiento en una estrategia de producto por fases.","tags":["Salud","Estrategia de Producto","Investigación UX","Pensamiento de diseño","Producto de IA","Investigación de Mercado"],"filters":["Healthcare","Product Strategy","AI Product"],"tools":["Claude AI","Gemini","NotebookLM","ChatGPT","Codex"],"images":{"cover":"/images/projects/calendar-keeper/thumbnails/calendar-keeper-cover.png","hero":"/images/projects/calendar-keeper/hero/calendar-keeper-hero.png","gallery":[]},"client_logos":[],"metrics":[],"team":["Estratega de producto","Investigador UX","Expertos en el ámbito sanitario","Socios de investigación de IA"],"my_role":["Diseñador Sr de Producto"],"problem":{"admin_pain_points":["El personal clínico (MFA, médicos independientes) dedica horas al día a gestionar interrupciones, reservas dobles y comprobaciones manuales del calendario en lugar de atender a los pacientes.","Los asistentes médicos alemanes manejan las tareas obligatorias de TI (recetas electrónicas, mensajes KIM, ePA) además de la programación para múltiples profesionales; Las fallas de TI los afectan directamente.","Las fallas de sincronización del calendario crean desincronizaciones silenciosas o bloqueos de día completo, lo que convierte los problemas técnicos en crisis operativas sin una ruta de recuperación visible.","Las preocupaciones sobre la soberanía de los datos son requisitos regulatorios (GDPR, BSI C5, alemán §203 StGB), no cosas agradables de tener."],"user_pain_points":["Los pacientes que regresan y intentan volver a reservar o administrar citas no tienen una ruta rápida de autoservicio, lo que los obliga a llamar, el mecanismo exacto que inunda al personal.","Los pacientes no tienen visibilidad de que sus datos de salud permanecen dentro de Europa, lo que erosiona la confianza en un mercado donde la soberanía de los datos es un mandato regulatorio.","Las plataformas de programación genéricas tratan cada reserva como un intervalo de tiempo intercambiable y no modelan las dependencias (sala, equipo, médico, preparación) que requieren los flujos de trabajo clínicos."]},"constraints":["Liquidez de red cero en la primera clínica; Los algoritmos de lista de espera y reabastecimiento necesitan un historial para funcionar.","Entorno regulatorio complejo: Francia y Alemania tienen diferentes modelos de dotación de personal (el 5% de los médicos de cabecera franceses tienen asistentes frente a los MFA alemanes que gestionan entre 3 y 19 profesionales).","Alta fricción de conmutación; El 44,8% de los consultorios alemanes teme que los datos no se migren de manera limpia, lo que suprimirá la demanda incluso de los usuarios insatisfechos.","La presencia de competidores difiere según el mercado: Doctolib domina Francia (23,2% de participación en PMS); Alemania muestra Doctolib a los 9 meses, lo que deja una ventana estrecha."],"methodology":{"name":"Design Thinking","steps":[{"step":1,"label":"Empatizar","description":"Descubrimiento de problemas, entrevistas con usuarios, mapeo de afinidades e investigación de mercados competitivos"},{"step":2,"label":"Definir","description":"Síntesis de personas, conocimientos de mapas de afinidad y declaraciones de problemas de causa raíz"},{"step":3,"label":"Idear","description":"Cómo-podríamos cuestionar, probar hipótesis y alinear estratégicamente"},{"step":4,"label":"Prototipo","description":"Estrategia de producto por fases, posicionamiento competitivo y secuenciación de comercialización"}]},"design_strategy":["Reclasificar la soberanía de datos y el posicionamiento de MFA primero como requisitos de entrada, no como diferenciadores; la verdadera ventaja defendible es la programación consciente de los recursos que no se interrumpe cuando lo hace la infraestructura.","Cree la versión inicial en torno a la reserva principal con dependencias de recursos (habitación, equipo, médico, preparación), no de reposición; la reposición necesita una lista de espera con historial para ser útil, que no existe el primer día.","Diseñe el modo degradado explícitamente: cuando la sincronización falla, muestre \"no sincronizado\" como un estado visible, cree una cola de reconciliación y permita que las citas se creen localmente con la identidad pendiente de verificación, convirtiendo una crisis en una condición conocida.","El primer GTM de Alemania está basado en evidencia: Doctolib ya posee Francia (23,2% de participación); Alemania lleva nueve meses en su impulso PMS (noviembre de 2025), lo que deja una ventana estrecha y mensurable.","El riesgo de migración es el obstáculo a la adopción, no las características; una ruta de migración de datos creíble y demostrable puede importar más que pulir el calendario."],"reflections":[{"title":"La competencia es real, pero no donde esperarías.","body":"Doctolib ya ganó Francia; Samedi envía nuestros diferenciadores reclamados a Alemania. La idea honesta es que necesitamos encontrar un ángulo que los competidores no hayan ocupado todavía, lo que resulta ser confiabilidad en modo degradado y honestidad sobre lo que es la Fase 1 versus la Fase 2."},{"title":"La estructura del mercado cambió la estrategia.","body":"Las diferencias de personal entre Francia y Alemania no son sólo variantes del mismo problema. Necesitan dos variantes de productos reales, dos enfoques de comercialización y dos narrativas ganadoras diferentes. Una solución única para todos fracasaría."},{"title":"La soberanía de los datos es algo que está en juego ahora.","body":"El cumplimiento del RGPD, BSI C5 y la Ley de IA de la UE es normativo, no diferenciador. La arquitectura del consentimiento y la transparencia importan más que la ubicación del alojamiento, porque todos los competidores afirman lo mismo."},{"title":"Las limitaciones obligaron a tomar una mejor decisión.","body":"Saber que no podemos respaldar el reabastecimiento el primer día (sin liquidez) nos obligó a preguntar qué funciona realmente en la primera cita de la primera clínica. La respuesta (reserva básica basada en los recursos) es más defendible que una función de lista de deseos."}],"nda_notice":"Este es un documento de estrategia en etapa inicial y un proceso de pensamiento de diseño. Los detalles del cliente y los datos competitivos se anonimizan o se agregan por mercado. La metodología y los hallazgos reflejan una investigación de mercado real y el descubrimiento de usuarios.","password":null,"external_link":null,"content_blocks":[{"id":"overview","type":"overview","title":"Descripción general del proyecto"},{"id":"design-thinking-facilitation","type":"custom","title":"Facilitación del pensamiento de diseño","body":"Estructuró el proceso de descubrimiento en cinco fases: empatizar, definir, idear y crear prototipos, utilizando la metodología del pensamiento de diseño para pasar de problemas no estructurados a estrategias viables. Cada fase se basó en la anterior, creando una cadena de conocimientos validados en lugar de suposiciones."},{"id":"user-research-synthesis","type":"custom","title":"Investigación y síntesis de usuarios","body":"Se realizó un descubrimiento en dos mercados distintos (Francia y Alemania), descubriendo nueve planteamientos de problemas distintos desde diferentes perspectivas de los usuarios: el administrador del calendario (médico independiente versus MFA), el paciente que regresa y el sistema mismo. Sintetizó los hallazgos cualitativos en personas, mapas de afinidad y análisis de causa raíz que revelaron las brechas estructurales que los competidores pasan por alto."},{"id":"competitive-intelligence","type":"custom","title":"Inteligencia Competitiva","body":"Realicé un riguroso análisis de mercado que cubrió a los proveedores actuales de PMS, los nuevos participantes y la dinámica del mercado. Se identificó que Doctolib ya es propietario de Francia (23,2% de participación en PMS), Samedi ocupa los supuestos diferenciadores en Alemania y el riesgo migratorio (no las características) es el verdadero obstáculo para la adopción. Esta investigación reformuló la estrategia y el enfoque de comercialización."},{"id":"solution-strategy","type":"custom","title":"Estrategia de solución","body":"Se tradujo la investigación a un enfoque de entrega por fases: reserva central con dependencias de recursos (Fase 1), confiabilidad en modo degradado (Fase 1) e incorporación/reabastecimiento (Fase 2). Reposicionado desde los supuestos diferenciadores (soberanía, MFA primero) a un ángulo defendible: programación consciente de los recursos que no se interrumpe cuando lo hace la infraestructura. Recomendado el primer GTM de Alemania según la evidencia del mercado."},{"id":"methodology","type":"custom","title":"Metodología: Design Thinking","body":"El proceso de descubrimiento siguió un enfoque de pensamiento de diseño estructurado en cuatro fases, complementado con herramientas de inteligencia artificial y una rigurosa investigación de mercado.","payload":{"phases":[{"phase":"Empatizar","description":"Descubrimiento de problemas, entrevistas con usuarios, mapeo de afinidades e investigación de mercados competitivos"},{"phase":"Definir","description":"Síntesis de personas, conocimientos de mapas de afinidad y declaraciones de problemas de causa raíz"},{"phase":"Idear","description":"Cómo-podríamos cuestionar, probar hipótesis y alinear estratégicamente"},{"phase":"Prototipo","description":"Estrategia de producto por fases, posicionamiento competitivo y secuenciación de comercialización"}]}},{"id":"empathize-intro","type":"custom","title":"Empatizar: descubrimiento de problemas e investigación de mercado","body":"La fase de empatía combinó el descubrimiento directo del usuario con una rigurosa inteligencia competitiva para comprender la forma real del mercado y las necesidades no satisfechas de los usuarios."},{"id":"problem-statements","type":"custom","title":"Declaraciones de problemas","body":"De la investigación surgieron nueve encuadres de problemas distintos en diferentes roles de usuario y mercados.","payload":{"problems":["Calendar Keeper necesita que el cronograma refleje la realidad sin volver a verificarlo manualmente, porque las interrupciones durante todo el día (llamadas, cambios, no presentaciones) cuestan tiempo clínico o causan doble reserva.","El MFA alemán necesita completar las tareas ordenadas por TI con menos clics y con menos puntos de falla, porque la mitad de las consultas alemanas tienen problemas de TI semanalmente, y esas fallas recaen en el MFA, no en el médico.","El MFA/MVZ alemán necesita clasificar y delegar la programación entre muchos profesionales desde una sola vista, porque un solo MVZ puede emplear hasta 19 MFA coordinando calendarios que una interfaz de un solo médico nunca fue diseñada para manejar.","El médico francés en solitario necesita que las llamadas de rutina sean atendidas sin salir de la consulta, porque el 30% de las llamadas ya quedan sin respuesta y cada una de ellas es un paciente perdido o una consulta interrumpida.","La disponibilidad confiable y en tiempo real sirve primero al Calendar Keeper, porque un calendario obsoleto es un riesgo de doble reserva para el personal antes de que sea una mala experiencia de búsqueda para un paciente.","Calendar Keeper necesita programar visitas de menor agudeza por teléfono o video en lugar de establecer de forma predeterminada a todos en un espacio en persona, porque protege la capacidad en persona para las visitas que realmente la necesitan.","Tanto el encargado del calendario como el paciente que regresa necesitan pruebas visibles de que los datos de salud permanecen en Europa, porque la soberanía es un factor que rompe la confianza y un requisito de cumplimiento para 2026.","El paciente que regresa necesita volver a reservar o administrar una cita existente rápidamente utilizando la identidad que ya está registrada, porque desviar esa llamada de rutina es el mecanismo completo por el cual la carga de trabajo del administrador del calendario realmente disminuye.","Un paciente que regresa y que ocasionalmente reserva para un dependiente nombrado necesita una ruta de entrada manual mínima, no una vinculación completa de la cuenta."]}},{"id":"user-needs","type":"custom","title":"Necesidades de los usuarios: grupos de usuarios provisionales","body":"De la investigación surgieron seis grupos distintos de usuarios, cada uno con necesidades específicas, puntos débiles y consecuencias del error. Estas son agrupaciones provisionales, no personas definitivas.","payload":{"groups":[{"group":"Pacientes: nuevos y existentes","goal":"Concierte una cita con poco esfuerzo y mínima divulgación de datos personales.","pain_points":["Abandona la reserva cuando los formularios solicitan información no esencial, o en Francia cuando el INS (Identifiant National de Santé) requiere detalles exactos de registro de nacimiento: alta fricción en el registro.","Frustrado por fallas técnicas: errores de páginas en blanco, cierres de sesión forzados, imposibilidad de hacer capturas de pantalla/copiar información de confirmación.","En Alemania, la doble suscripción (correo electrónico/SMS) puede dejar un espacio sin confirmar y efectivamente perdido.","Frustrado cuando \"no hay citas en línea disponibles\" hace que la herramienta parezca un esfuerzo desperdiciado.","Erosión de la confianza cuando una capacidad lingüística enumerada (por ejemplo, 'habla inglés') no se sostiene en persona: la precisión de los metadatos del profesional es importante para la seguridad, no solo para la satisfacción.","La desconfianza en las plataformas que se percibe que envían notas o datos de consulta a proveedores de IA fuera de la UE o a terceros: esta es una causa de abandono impulsada por la confianza."],"consequence":"Reservas perdidas/duplicadas, embudo abandonado o (en el caso de falta de coincidencia de idiomas) un riesgo para la calidad de la atención.","jtbd":"Cuando necesito ver a un médico y no estoy seguro del proceso, quiero encontrar y confirmar un espacio real y disponible sin dar más información de la necesaria, para poder confiar en que la cita realmente se realizará."},{"group":"Cuidadores / personas que reservan para otra persona","goal":"Administre las citas para un dependiente (niño, padre anciano) con la misma facilidad que para ellos mismos.","pain_points":["Un tercio de las citas francesas se reservan para un familiar; ~46 % de los pacientes tienen una cuenta relativa vinculada; este no es un caso marginal, es un flujo central.","La entrada de la fecha de nacimiento mediante el desplazamiento desplegable mes a mes es un punto de fricción específico y con nombre para este grupo.","Implicación de permisos: el producto necesita un modelo de 'administración en nombre de' de primera clase, no un complemento."]},{"group":"Pacientes mayores/con menor alfabetización digital","goal":"Acceda a la reserva de citas con el soporte adecuado para su nivel de comodidad tecnológica.","pain_points":["5,9 millones de usuarios franceses de Doctolib tienen más de 65 años (señal de escala), pero los pacientes alemanes mayores de 80 años se describen como \"abrumados\" por las herramientas digitales, muchos de ellos sin teléfonos inteligentes ni PC; esta es una brecha específica del mercado, no el mismo problema en ambos países.","Los usuarios con discapacidad visual necesitan flujos de reserva accesibles; Todos los pacientes necesitan claridad sobre la accesibilidad física (acceso en silla de ruedas) de la propia consulta."],"consequence":"Exclusión del autoservicio, que devuelve la carga a las líneas telefónicas y se conecta directamente al punto débil de la recepcionista."},{"group":"Recepcionistas / Asistentes Médicos (MFA)","goal":"Mantenga la programación precisa con un mínimo de retrabajo manual, mientras maneja interrupciones constantes.","pain_points":["~30% de las llamadas a médicos quedan sin respuesta; las llamadas de rutina (verificaciones de seguros, reprogramaciones) entierran la recepción.","Los MFA alemanes se sienten frustrados por los flujos de trabajo de TI que requieren muchos clics (mensajería KIM, recetas electrónicas) y por los fallos del sistema o lector de tarjetas después de las actualizaciones.","Diferencia estructural: en Alemania, el MFA es un usuario avanzado: 3 años de formación, realiza tareas clínicas (extracciones de sangre, vendajes) y administrativas (reservas, facturación); promedio de 3,4 por práctica en solitario, hasta 19 en MVZ. En Francia, sólo ~5% de los médicos de cabecera emplean un MFA, y las tareas son principalmente administrativas."],"design_implication":"La recepcionista no es una sola persona: Alemania necesita una interfaz centrada en asistentes y con capacidad de delegación; Francia necesita que el médico siga siendo el actor central. Esta es una de las tensiones más agudas de todo el proyecto."},{"group":"Médicos / clínicos","goal":"Maximice el tiempo clínico, minimice la carga administrativa.","pain_points":["Diferencia estructural en cómo los médicos usan el tiempo: Alemania: 9,8 contactos/año, ~8 min/visita, alta rotación de pacientes, necesidad de documentación con un solo clic. Francia: 5,9 contactos/año, 16 a 18 min/visita, favorece las notas longitudinales y la IU de formato más largo.","~10 horas/semana perdidas debido a cuellos de botella administrativos (citado como el punto débil que Doctolib está atacando con el manejo de llamadas de IA)."],"consequence":"Las reservas dobles o el tiempo perdido reducen directamente la capacidad clínica facturable: este grupo es sensible a los ingresos por errores de programación de una manera que los pacientes no lo son."},{"group":"Gerentes/administradores de clínicas y equipos internos de CX/soporte","status":"🔴 Research gap","note":"Aún no hay evidencia directa. El material original se dirige a recepcionistas y médicos, pero no a propietarios/gerentes de consultorios ni a equipos de implementación internos. Marcado como una necesidad de investigación abierta en lugar de necesidades de invención."}]}},{"id":"user-needs-context","type":"custom","title":"Contexto: panorama regulatorio, operativo y competitivo","body":"Las necesidades de los usuarios no se pueden entender sin el contexto regulatorio, laboral y competitivo que las configura.","payload":{"regulatory":{"title":"Contexto regulatorio y de gobernanza","france":"Centralizado — State + Assurance Maladie establece tarifas, certificaciones y negociaciones a nivel nacional. HDS v2.0: certificación obligatoria de alojamiento de datos sanitarios. Transición a V2.0 antes del 16 de mayo de 2026; Las normas de soberanía de septiembre de 2026 exigen el alojamiento y la divulgación de exposición legal fuera de la UE únicamente en el EEE (por ejemplo, la Ley CLOUD de EE. UU.).","germany":"Descentralizado: los organismos corporativistas (G-BA, KV regionales) controlan el acceso al mercado; Bedarfsplanung restringe dónde y cómo los médicos pueden incluso establecer su consulta. Infraestructura Telemática (TI): red cerrada obligatoria; Fecha límite de integración de ePA: 1 de octubre de 2025; Autenticación mediante tarjetas físicas SMC-B/eHBA. El 50% de los médicos alemanes informan semanalmente sobre problemas técnicos de TI, una apertura competitiva declarada para un participante más estable."},"workforce":{"title":"Fuerza laboral y contexto operativo","gp_density":"Francia: gran número de médicos de cabecera (107/100.000) y orientado al volumen de atención primaria. Alemania, con muchos especialistas (117/100k), con el doble de cirujanos ambulatorios y aproximadamente el triple de ginecólogos, lo que significa que las necesidades de programación de Alemania se inclinan hacia la reserva de recursos complejos (habitaciones, equipos, bloques quirúrgicos), no solo franjas horarias.","consultation_rhythm":"Francia: 5,9 visitas/año, 16-18 min/visita, favorece las notas longitudinales. Alemania: 9,8 visitas/año, ~8 min/visita, alta rotación de pacientes, necesidad de documentación con un solo clic. Esto genera necesidades de densidad de información fundamentalmente diferentes en la interfaz de usuario de reserva y documentación."},"competitive":{"title":"Panorama competitivo","incumbent":"Doctolib es el titular dominante, ya que pasó de una herramienta de reservas a un sistema operativo de práctica completa y lanzó su PMS alemán a finales de 2025, con gestión de llamadas mediante IA y pagos integrados basados en Adyen.","trust_gaps":"Carga de trabajo de MFA debido a solicitudes no seguras y una crisis de confianza más amplia en materia de 'soberanía de datos', nombrada como una apertura específica para un entrante soberano/privacidad primero.","pricing":"Samedi ~35–59€/usuario; Doctolib ~139€/profesional."},"business":{"title":"Contexto empresarial: explícitamente sin resolver","note":"La secuenciación de GTM (Francia primero versus Alemania primero) no está decidida. Esto es importante para el alcance de la empatía: si no sabemos qué mercado se lanza primero, debemos mantener nuestra elección de flujo de trabajo prioritario defendible en ambos mercados en lugar de optimizar estrictamente para uno. El modelo de precio/agrupación con la suite existente no está definido."}}},{"id":"competitive-analysis","type":"custom","title":"Investigación competitiva: tres hallazgos que cambiarán el mercado","body":"El análisis de mercado reveló que las suposiciones convencionales sobre nuestra posición eran incorrectas.","payload":{"findings":[{"title":"⚠️ Doctolib ya ha conquistado el mercado francés de PMS","body":"Doctolib es el software de gestión de consultas de médicos de cabecera más utilizado en Francia en marzo de 2026, con el 23,2% de las transmisiones electrónicas de solicitudes de asistencia, por delante de Weda (14,0%), Medistory (10,1%) y HelloDoc (8,1%). Pasó del 0% al 23,2% en cinco años, y lo hizo sin adquisiciones, simplemente conectando software a su plataforma de reservas.\n\nEsto invierte nuestro encuadre anterior. En Francia, Doctolib se encarga ahora de la distribución a pacientes y a la práctica. Nuestro argumento de que \"somos fuertes donde ellos son débiles\" no se sostiene."},{"title":"🔵 En Alemania, la misma medida apenas está en marcha, y ese es un período estrecho y anticuado.","body":"El PVS alemán de Doctolib se lanzó en noviembre de 2025, inicialmente solo para médicos de cabecera, pediatras y ginecólogos. En la evaluación Zi 2026, Doctolib tenía un tamaño de muestra insuficiente para producir datos válidos de usabilidad, NPS o tasa de error.\n\nSi se lee junto con el hallazgo de Francia, este es el argumento empírico más fuerte a favor del primer GTM de Alemania, una decisión que nuestros documentos catalogan como indecisa. Francia es un mercado que Doctolib ya ha conquistado; Alemania es uno de los que empezó a tomar hace nueve meses."},{"title":"⚠️ Samedi ocupa nuestros diferenciadores reclamados","body":"Samedi es una plataforma SaaS con sede en Berlín utilizada por más de 48.000 médicos en aproximadamente 10.000 instituciones en la región DACH, que ofrece reservas en línea con lista de espera, planificación dinámica de recursos, formularios digitales con firma electrónica y pago integrado, respaldados por cifrado de extremo a extremo patentado por la UE, certificación TÜV e ISO 27001/9001.\n\nEs decir, programación consciente de los recursos más posicionamiento de soberanía más lista de espera/reabastecimiento, ya enviados, a escala. Dos de nuestros tres diferenciadores reclamados están ocupados. Sus verdaderas brechas: ningún portal público de búsqueda de pacientes, precios por médico que se acumulan para las prácticas grupales, ningún nivel de entrada gratuito y ninguna incorporación de autoservicio."}]}},{"id":"market-dynamics","type":"custom","title":"Dinámica del mercado: la palanca de desplazamiento real","body":"Lo que realmente impulsa el cambio no es la satisfacción, sino las barreras al cambio y el riesgo de migración.","payload":{"key_insight":"El 33,3% de los consultorios alemanes quieren cambiar de PMS (en comparación con el 44,4% en 2024). Uno de cada tres está comprando activamente. Pero la disminución no se debe a una mayor satisfacción; se debe a las barreras de cambio percibidas.","displacement_dynamics":[{"signal":"Prácticas que quieren cambiar de PMS","figure":"33,3% en 2025 (frente al 44,4% en 2024)","meaning":"Demanda suprimida, no satisfecha"},{"signal":"Bloqueador superior","figure":"El 44,8% teme que los datos no se migren limpiamente","meaning":"La migración es un problema del producto, no de las características"},{"signal":"Cambiar motivos","figure":"Usabilidad (1º), tarifas (2º), soporte (3º)","meaning":"La usabilidad es una palanca de diseño; el titular tiene mala experiencia"},{"signal":"Resultado posterior al cambio","figure":"83,9% reporta una mejora significativa","meaning":"El cambio funciona, pero la gente está cambiando a sistemas que ya tienen mala calificación"}],"proof":"AxiSanté (CGM) cayó del 16% en 2019 a menos del 0,2% en 2026 después de que se anunció el fin del soporte. La titularidad colapsa rápidamente una vez que se rompe la confianza."}},{"id":"sovereignty-context","type":"custom","title":"Reclamaciones de soberanía: debidamente escalonadas","body":"La soberanía de los datos es un tema vivo y controvertido, no un diferenciador que podamos poseer.","payload":{"reality":"Doctolib utiliza IA de Google, Microsoft y Anthropic en su asistente de consulta. Bajo escrutinio; acusaciones de que los datos de los pacientes pueden estar expuestos a proveedores de tecnología estadounidenses. Doctolib niega uso indebido; La OCDE lo clasifica como un peligro más que como un incidente realizado. La Ley de IA de la UE entrará en vigor el 2 de agosto de 2026.","honest_read":"El vector de confianza es real y actualmente activo, pero la postura de cumplimiento formal de Doctolib es fuerte, y nuestra propia ventaja descansaría en la arquitectura de consentimiento y la transparencia, no en la ubicación del alojamiento. La ubicación del alojamiento es algo que está en juego; todos los competidores lo reclaman.","takeaway":"'Somos el soberano' no es un diferenciador defendible. \"No utilizamos los datos de sus pacientes de forma predeterminada y podemos mostrarle exactamente lo que utilizamos\"."}},{"id":"define-intro","type":"custom","title":"Definir: Personas, Patrones y Causas Raíces","body":"La fase de definición sintetizó la investigación sobre modelos de personalidad e identificó los problemas estructurales debajo de las quejas superficiales."},{"id":"affinity-map","type":"custom","title":"Mapa de afinidad: lo que da forma al flujo primario","body":"La investigación reveló profundas diferencias estructurales que dan forma a las decisiones sobre la arquitectura del producto.","payload":{"findings":[{"title":"Francia y Alemania cuentan con personal como dos profesiones diferentes","details":"La densidad de médicos de cabecera es 107/100k en Francia frente a 66/100k en Alemania; El ritmo de consulta sigue la misma división: 5,9 visitas/año de 16 a 18 minutos en Francia, 9,8 visitas/año de ~8 minutos en Alemania. Es por eso que Calendar Keeper necesita dos variantes reales en lugar de una interfaz con cambio de idioma."},{"title":"El calendario tiene que ser confiable, no sólo presente","details":"Los pacientes que realizan búsquedas exhaustivas y pulsan \"no hay citas disponibles\" describen la herramienta como una pérdida de tiempo. En lo que respecta a las operaciones, el 81% de los consultorios alemanes informan errores en el conector TI y el 82% informa fallas al leer la tarjeta eGK, lo que significa que el calendario en sí deja de ser confiable antes de que el paciente lo vea."},{"title":"La recepción ya está bajo el agua.","details":"Aproximadamente el 30% de las llamadas a los médicos quedan sin respuesta. Los MFA alemanes citan específicamente los flujos de trabajo de TI con muchos clics y las fallas de los lectores de tarjetas como factores estresantes recurrentes. Las 10 horas semanales perdidas en trabajo administrativo es exactamente a lo que apuntan los competidores con el manejo de llamadas mediante IA."},{"title":"La soberanía de los datos es una condición de confianza, no una característica","details":"La confianza se rompe cuando los datos de la consulta parecen llegar a modelos de IA no europeos o a terceros. Esto no es específico de un segmento: le importa por igual al encargado del calendario (exposición al cumplimiento) y al paciente que regresa (confianza), y las reglas de septiembre de 2026 hacen que el hospedaje exclusivo del EEE sea un requisito en lugar de una preferencia."}]}},{"id":"personas","type":"custom","title":"Protopersonas","body":"Surgieron dos arquetipos de usuario distintos, no variaciones de idioma.","payload":{"primary":{"title":"El encargado del calendario","description":"Un rol, desempeñado por una persona diferente dependiendo del mercado: quien posee el cronograma y necesita que sea cierto sin tener que volver a verificarlo constantemente.","job":"Cuando mi agenda se ve interrumpida todo el día por llamadas, cambios y ausencias, quiero que el calendario siempre sea fiel sin que yo lo vuelva a revisar, para no perder tiempo clínico ni agendar dos veces a alguien.","france":{"title":"Médico en solitario","details":"Dirige la recepción personalmente, ya que solo ~5% de los médicos de cabecera franceses emplean un asistente. Atiende a los pacientes durante 16 a 18 minutos seguidos y absorbe las interrupciones entre consultas en lugar de delegarlas. Necesita que se atiendan llamadas de rutina (reprogramación, preguntas sobre seguros) sin salir de la sala de examen."},"germany":{"title":"MFA (Medizinische Fachangestellte)","details":"Clínicamente capacitado durante tres años, administra el calendario para múltiples profesionales: 3,4 en promedio en una práctica individual, hasta 19 en una MVZ más grande. Recibe consultas más breves y frecuentes (~8 minutos, 9,8 visitas/año) y dedica tiempo real a tareas obligatorias de TI (mensajes KIM, recetas electrónicas, ePA). Aproximadamente la mitad de los consultorios alemanes informan semanalmente problemas técnicos de TI, y esos fallos repercuten en el MFA. Necesita clasificar y delegar entre muchos profesionales desde una única vista."}},"secondary":{"title":"El paciente que regresa","description":"Una superficie estrecha y deliberadamente delgada. Su única función es permitir que un paciente que ya tiene un registro vuelva a reservar, cancelar o gestionar una cita existente sin llamar.","scope":"Ocasionalmente incluye la reserva para un dependiente nombrado, ingresada manualmente para esa cita, no un perfil guardado y vinculado. Excluye deliberadamente la verificación de identidad de nuevos pacientes, la administración completa de cuentas vinculadas y los informes/análisis en v1."}}},{"id":"root-causes","type":"custom","title":"Causas fundamentales: lo que realmente está roto","body":"La investigación descubrió que los problemas obvios ocultan problemas estructurales más profundos.","payload":{"q_a":[{"q":"¿Cuáles son los problemas centrales?","a":"Las plataformas de programación genéricas tratan cada reserva como una franja horaria intercambiable. Una cita clínica a menudo depende de una sala, un equipo, un médico específico y el tiempo de preparación juntos, y ninguna arquitectura de la competencia modela esa dependencia porque fue construida del lado de la demanda (el linaje de Doctolib). Segundo problema: cuando falla la sincronización (interrupción de TI, lector eGK caído), la mayoría de los sistemas se desincronizan silenciosamente o se bloquean durante todo el día, convirtiendo un problema técnico en una crisis operativa."},{"q":"¿Cuáles son las causas fundamentales?","a":"La brecha de dependencia es estructural, no una brecha de características. Está integrado en cómo se diseñó el modelo de datos subyacente. El problema de la falla de sincronización es una omisión de diseño: nadie diseñó para el modo degradado, por lo que la falla no tiene un estado visible, ni una ruta de reconciliación ni un valor predeterminado seguro."},{"q":"¿Cuáles son las perspectivas de las partes interesadas?","a":"La clínica evalúa las reservas teniendo en cuenta los recursos durante la demostración de ventas, no meses después. Al director de CX le importa una distinción: si una falla de sincronización se convierte en un ticket de soporte o en una crisis en toda regla. El riesgo real de la ingeniería es el acceso de escritura y la calidad del esquema en la integración, y las dependencias de recursos son exactamente lo que expone una mala sincronización."},{"q":"¿Cuáles son las limitaciones actuales?","a":"Liquidez cero en la primera clínica (sin historial, sin datos de lista de espera), lo que descarta cualquier cosa que necesite un efecto de red para ser útil el primer día."}]}},{"id":"ideate-intro","type":"custom","title":"Idear: Cómo podríamos y cuestionamiento estratégico","body":"La fase de ideación utilizó preguntas estructuradas para pasar de los problemas a hipótesis procesables."},{"id":"hmw-questions","type":"custom","title":"Preguntas de cómo podríamos hacerlo","body":"Cinco categorías de preguntas abarcaron el espacio de soluciones y probaron los supuestos.","payload":{"categories":[{"type":"Amplifying","example":"¿Cómo podríamos amplificar la confianza en la programación en el momento en que falla la sincronización?","answer":"Hacer que 'no sincronizado' sea un estado visible y con nombre en lugar de un espacio silencioso, para que el personal de recepción vea el modo degradado como una condición conocida, no como un fallo inexplicable."},{"type":"Removing","example":"¿Cómo podríamos eliminar por completo el modo de falla de bloqueo de día completo?","answer":"Permita que las citas se creen localmente con la identidad pendiente de verificación cuando el lector de eGK o TI falle, y colóquelas en cola para su conciliación en lugar de detener la programación de todo el día."},{"type":"Exploring","example":"¿Cómo podríamos explorar cómo debería ser operativamente una cola de conciliación?","answer":"Prototíquelo como un flujo de 1 a 2 pantallas (insignia de estado, vista de cola) y pruebe si el personal de recepción puede actuar en consecuencia sin capacitación, ya que esto es lo que se muestra al jefe de CX."},{"type":"Questioning assumptions","example":"¿Cómo podríamos desafiar el supuesto de que la 'soberanía de los datos' y el 'MFA primero' son diferenciadores?","answer":"Reclasificar ambos como requisitos de ingreso, no como puntos de venta. Todos los competidores ya los reclaman, por lo que liderar con ellos desperdicia el espacio de diferenciación que realmente puede poseer la programación consciente de los recursos."},{"type":"Unexpected resource","example":"¿Cómo podríamos utilizar la función de reposición diferida como prueba de juicio en lugar de como un espacio para ocultar?","answer":"Encuadrelo explícitamente en la clínica: el reabastecimiento necesita una lista de espera con historial para tener algún aporte, y esa liquidez no existe en el primer mes, por lo que es la Fase 2 por diseño, no por supervisión."}]}},{"id":"question-characteristics","type":"custom","title":"Características de las preguntas: Rigor de las pruebas","body":"El conjunto HMW resistió cuatro pruebas de validez.","payload":{"tests":[{"test":"Alcance","description":"Cada pregunta se centra en las dos pantallas que realmente se envían (reserva principal, modo degradado), no en una lista de deseos."},{"test":"Accionable","description":"Se asignan directamente a lo que se construye y se demuestra."},{"test":"Enmarcado positivamente","description":"Alrededor de 'cómo se ve el modo degradado confiable' en lugar de 'cómo ocultamos nuestro problema de sincronización'."},{"test":"Factible","description":"Ninguno requiere un efecto de red o liquidez existente, razón por la cual el backfill queda completamente fuera de este conjunto. Aquí todo funciona en la primera cita de la primera clínica."}]}},{"id":"strategic-alignment","type":"custom","title":"Alineamiento Estratégico","body":"Cada pregunta se conecta directamente con los problemas del usuario, el objetivo comercial y el riesgo técnico.","payload":{"alignment":[{"lever":"Dolor del usuario","connection":"El personal de recepción pierde la confianza en el cronograma en el momento en que la sincronización se interrumpe silenciosamente. Las preguntas de eliminación y exploración apuntan directamente a eso."},{"lever":"Objetivo de negocio","connection":"El momento de evaluación de ventas es el flujo central consciente de los recursos, por lo que cada HMW aquí fortalece ese flujo o lo protege del modo de falla que lo socavaría durante una demostración."},{"lever":"Restricción técnica","connection":"El HMW de cuestionamiento y suposiciones obliga al equipo a probar el acceso de escritura y la calidad del esquema con anticipación, ya que ahí es donde surgiría primero una mala sincronización."}]}},{"id":"prototype-intro","type":"custom","title":"Prototipo: Posicionamiento y estrategia de producto por fases","body":"La fase de prototipo tradujo los descubrimientos en un plan de comercialización concreto y secuenciado."},{"id":"solution-strategy","type":"custom","title":"Solución: Nuevo flujo de héroe","body":"Un enfoque de tres niveles que prioriza lo que funciona desde el primer día.","payload":{"layers":[{"tier":"Núcleo (alta fidelidad)","name":"Appointment-type setup with resource dependency → booking that respects it","details":"Sala + equipamiento + practicante + preparación, donde las plataformas genéricas tratan todo como franjas horarias.","why":"Funciona con liquidez cero. Es útil en la primera cita de la primera clínica. Es la verdadera brecha estructural: los competidores no hacen esto porque su arquitectura nació del lado de la demanda. Es el flujo que la clínica evalúa durante la venta, no seis meses después. Pone a prueba la suposición técnica más peligrosa (acceso de escritura y calidad del esquema), porque las dependencias de recursos son exactamente lo que rompe una mala sincronización."},{"tier":"Secundario (alta fidelidad, 1 o 2 pantallas)","name":"Degraded mode and conflict resolution","details":"Estado visible \"no sincronizado\", cola de conciliación, cita creada localmente con identidad pendiente de verificación, nunca un bloqueo de día completo.","why":"Convierte el problema de falla de sincronización en una respuesta diseñada en lugar de un reclamo vacío. Cuando falla la TI o el lector eGK, el programa sigue siendo confiable y operable. Esto es lo que el jefe de CX quiere escuchar, porque es la diferencia entre un ticket y una crisis."},{"tier":"Terciario (baja fidelidad, Fase 2)","name":"Time-to-first-configured-schedule (onboarding)","details":"Estructuras alámbricas que documentan el flujo de configuración sin pulir.","why":"La incorporación entra en alcance, pero como una estructura alámbrica. No es necesario que sea bonito; necesita existir y ser medido. El reabastecimiento pasa a la Fase 2 con una justificación explícita: el reabastecimiento necesita una lista de espera con historial para existir; Lo aplazamos porque en el mes 1 no tiene entrada y su valor depende de la liquidez que esta liberación aún no crea. Esto indica antigüedad: sabemos qué importa primero."}]}},{"id":"competitive-positioning","type":"custom","title":"Reposicionamiento: Lo que realmente diferencia","body":"Reformule la narrativa basándose en lo que los competidores no pueden ocupar.","payload":{"reframe":[{"claim":"Soberanía de datos y posicionamiento MFA-first","before":"Diferenciadores","after":"Requisitos de ingreso","reason":"Cada competidor los reclama; no nos diferencian."},{"claim":"Programación basada en recursos","status":"Partially occupied","angle":"Samedi lo envía, pero el verdadero diferenciador defendible que queda es más limitado y más honesto."}],"defensible_differentiator":"Programación consciente de los recursos que no se interrumpe cuando lo hace la infraestructura. Es verificable, mensurable y no depende de un efecto de red que no tengamos."}},{"id":"gmt-strategy","type":"custom","title":"Estrategia de comercialización: Alemania primero","body":"La selección de mercado basada en evidencia pasa de indeciso a recomendado.","payload":{"prior":"La secuencia GTM estaba indecisa","evidence":"Francia es un mercado que Doctolib ya ha conquistado (23,2% de participación en PMS). Alemania es uno de los países que comenzó a tomar hace nueve meses (noviembre de 2025), con un tamaño de muestra insuficiente para obtener datos de usabilidad válidos. Una ventana estrecha, mensurable y favorable.","recommendation":"Primer GTM en Alemania. Traiga a la conversación con las partes interesadas una recomendación con evidencia, no una suposición de diseño."}},{"id":"strategic-recommendations","type":"custom","title":"Recomendaciones estratégicas: lo que cambió","body":"La investigación de mercado reformuló el alcance y posicionamiento inicial.","payload":{"table":[{"prior":"Doctolib es una herramienta de reservas que se traslada al PMS","status":"⚠️ False in France — it's #1 in PMS","action":"Reescribe la diapositiva competitiva"},{"prior":"Secuencia GTM indecisa","status":"🔵 Evidence now favours Germany-first","action":"Llevar como recomendación a las partes interesadas"},{"prior":"La programación consciente de los recursos es nuestro diferenciador","status":"⚠️ Samedi ships it at scale","action":"Necesario, no suficiente — reposicionar"},{"prior":"La soberanía es nuestro diferenciador","status":"⚠️ Occupied by both rivals","action":"Cambio a arquitectura de consentimiento + transparencia"},{"prior":"La inestabilidad heredada es la cuña","status":"🔵 Confirmed and quantified","action":"Mantener; fortalecer con datos Zi"},{"prior":"Arquitectura de tres capas","status":"✅ Unaffected","action":"Mantener"},{"prior":"Usuario principal de Calendar Keeper","status":"✅ Unaffected — Doctolib built its PVS in close collaboration with MFAs and doctors","action":"Mantener; valida que el MFA es el objetivo correcto"},{"prior":"—","status":"🆕 Migration risk as adoption blocker","action":"Agregar a los requisitos iniciales; posiblemente más decisivo que cualquier característica del calendario"}]}},{"id":"new-constraints","type":"custom","title":"Nuevas restricciones técnicas y regulatorias","body":"La investigación de mercado reveló requisitos de cumplimiento que no estaban en el informe original.","payload":{"constraint":"Los proveedores de PVS en la nube en Alemania se enfrentan al artículo 203(3–4) StGB, art. 28 GDPR, §393 SGB V y BSI C5 requisitos de certificación, y un acuerdo de procesamiento de datos por sí solo no elimina la exposición al secreto profesional del derecho penal.","requirement":"La evaluación de conformidad de KBV y la conexión TI también son obligatorias para los sistemas en la nube.","implication":"Esta es una barrera de entrada nativa de la nube que ninguno de nuestros cuatro documentos de proyecto capturó. Añadir al registro de restricciones técnicas."}},{"id":"market-tailwinds","type":"custom","title":"Vientos de cola del mercado y métricas de referencia","body":"La investigación confirmó y cuantificó señales clave de demanda.","payload":{"german_infrastructure":["El 82% de los consultorios reportan problemas recurrentes al leer la tarjeta sanitaria electrónica (eGK)","El 81% reporta errores frecuentes de conexión de TI","El 71 % informa dificultades periódicas para crear recetas electrónicas"],"patient_adoption":"El 64% de los alemanes ha reservado una cita médica en línea al menos una vez, frente al 36% en 2023: un fuerte viento de cola para la parte de la versión inicial orientada al paciente."}}]}$case_es0$::jsonb
